/* DAWAH X — ahmad, অধ্যায় 20 · খণ্ড 20 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][20]=[[3801,3801,"","আমরা কথা বলেছি ভাল করার চেয়ে ভালো কিছু করার চেয়ে ভালো কিছু করার কথা, ঈশ্বর আমার দুঃখ থেকে চাঁদ ফেলে দিয়েছেন আর তারপর বলেছেন এখানে আর পাপ যেন না হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏رَمَى الْجَمْرَةَ مِنْ ‏ ‏بَطْنِ الْوَادِي ‏ ‏ثُمَّ قَالَ هَاهُنَا وَالَّذِي لَا إِلَهَ غَيْرُهُ كَانَ يَقُومُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3802,3802,"","আমি একটি ভাল ছেলের সাথে যৌন সম্পর্ক করার কথা বলেছিলাম, আমি তার জন্য ঈশ্বরের কাছে প্রার্থনা করেছিলাম এবং তিনি তার জন্য প্রার্থনা করেছিলেন এবং আমার বাবার কথা শুনে অনেক দূর চলে গিয়েছিলেন। ঈশ্বর এই কাজে দুই ঘন্টা ব্যয় করেছেন। আমি আপনাকে বলছি, আমি যদি আমার বাবা মারা যান, তাহলে আপনি কি এই বিষয়ে কথা বলতে পারবেন? আপনি কি জানেন? আপনি যদি আপনি জানেন, আপনি আপনার সন্তান না আপনি জানেন, আপনি কি? আপনি জানেন, আপনি জানেন, আপনি আপনার সন্তান আপনার সন্তান আপনার জন্য একটি মেয়ে আছে? আপনি কি? আপনি যদি আপনি জানেন, আপনি আপনার সন্তান আপনি জানেন, আপনি আপনার সন্তান আপনি কি? আপনি আপনার জন্য একটি মহান সুযোগ আছে? আপনি কি? আপনি কি? আপনি আপনার বাবা আপনার জন্য একটি মহান? আপনি কি? আপনি আপনার বাবা? আপনার বাবা? আপনি কি জানেন? আপনার বাবা আপনার বাবা আপনার জন্য একটি মহান সুযোগ আছে? এবং আপনার জন্য একটি বিশেষ সুযোগ আপনার জন্য একটি বিষয় কি আছে?","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[3803,3803,"","ঈশ্বরের দয়ায়, ঈশ্বরের দয়ায় তাকে এটা করতে হয়েছে আর চাঁদকে বলা হয়েছে যে সে মারা গেছে। সাহস, সে শপথ নিয়ে চলে গিয়েছিল, আর আমরা তার গর্তে গিয়ে তাকে মেরেছিলাম, তোমার সম্মান করে তাকে হত্যা করে হত্যা করেছি, ঈশ্বরের দোহাইর কাছে প্রার্থনা করা অনেকটা সে বলছে আর আমরা ভাল আছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَارٍ فَنَزَلَتْ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏قَالَ فَإِنَّا ‏ ‏نَتَلَقَّاهَا مِنْ ‏ ‏فِيهِ فَخَرَجَتْ حَيَّةٌ مِنْ جُحْرِهَا ‏ ‏فَابْتَدَرْنَاهَا ‏ ‏فَسَبَقَتْنَا فَدَخَلَتْ جُحْرَهَا فَقَالَ ‏ ‏وُقِيَتْ شَرَّكُمْ وَوُقِيتُمْ شَرَّهَا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِثْلَهُ قَالَ وَإِنَّا لَنَتَلَقَّاهَا مِنْ ‏ ‏فِيهِ رَطْبَةً ‏","","",""],[3804,3804,"","আমি শপথের সীলের ব্যাপারে কথা বলেছিলাম, আমাকে তার হাতে ফিরে যেতে বলা হয়েছে আর লর্ডকে পেতে হবে। আল্লাহ তাকে তার আত্মা খুঁজে পেতে আমাদের আশীর্বাদ করেছেন। তাকে বলতে বলল যে সে ইতিমধ্যে করেছে, তুমি এটা করবে আর তুমি গুনতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ الْحُرِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ مُخَيْمِرَةَ ‏ ‏قَالَ ‏ ‏أَخَذَ ‏ ‏عَلْقَمَةُ ‏ ‏بِيَدِي ‏ ‏وَحَدَّثَنِي ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏أَخَذَ بِيَدِهِ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَعَلَّمَهُ التَّشَهُّدَ فِي الصَّلَاةِ قَالَ قُلْ ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَفِظْتُ عَنْهُ إِنْ شَاءَ اللَّهُ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ قَالَ فَإِذَا قَضَيْتَ هَذَا ‏ ‏أَوْ قَالَ فَإِذَا فَعَلْتَ هَذَا ‏ ‏فَقَدْ قَضَيْتَ صَلَاتَكَ إِنْ شِئْتَ أَنْ تَقُومَ فَقُمْ وَإِنْ شِئْتَ أَنْ تَقْعُدَ فَاقْعُدْ ‏","","",""],[3805,3805,"","আমরা বাবা কথা বলেছিলাম, তিনি আমাদের কথা বলেছিলেন, আমরা আমার ছেলের ব্যাপারে কথা বলেছি। লর্ড তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে তিনি বলেছেন যে প্রভুর স্বর্গ ভয় পাওয়ার ভয় কে নষ্ট করবে। আমি আপনাদের কাছে প্রার্থনা করছি। আমি আপনাদের ধন্যবাদ। আমি আপনাদের বলছি, আমার ছেলে-মেয়েরা আমার কাছে, আমি আমার ছেলে। আমি আপনাদের ধন্যবাদ জানাতে চাই, আমি আমার বাবা, আমি আমার ছেলের সাথে, আমি আমার ছেলের সাথে তোমার সাথে কথা বলেছি। আমি এখন আমার ছেলের মত আচরণ করতে চাই। আমি এখন তোমার কাছে এটা একটা ভালো হবে। কিন্তু আমি আপনাদের কাছে এটা একটা ভালো জিনিস আছে। কিন্তু আমি আপনাদের কাছে এটা একটা বিষয়। আমি আপনাদের সাথে কথা বলেছি। আমি জানি না। আমি জানি, আমি জানি না যে, আমি কি করবো না। আমি জানি না। আমি জানি না, আমি জানি না যে, আমি কি, আমি জানি না। আমি জানি, আমি জানি না। যে মানুষ মারা যাবে তাকে জনতার পাশ দিয়ে পাশ কাটিয়ে দেওয়া হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ يَعْنِي الطَّيَالِسِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لِقَوْمٍ يَتَخَلَّفُونَ عَنْ الْجُمُعَةِ لَقَدْ ‏ ‏هَمَمْتُ أَنْ آمُرَ رَجُلًا ‏ ‏يُصَلِّي بِالنَّاسِ ثُمَّ أُحَرِّقَ عَلَى رِجَالٍ بُيُوتَهُمْ يَتَخَلَّفُونَ عَنْ الْجُمُعَةِ ‏","","",""],[3806,3806,"","আমরা আমার বাবার কথা বলেছিলাম ভালো খেলার চেষ্টা করতে, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তিনি আত্মসমর্পণ করবেন, প্রভু, ঈশ্বর একজন অজানা লোককে শক্তিশালী করেছেন এবং হত্যা করেছেন। আমার একজন ছেলে আছে। আমি তাকে বলি, ঈশ্বর সবসময় আমাদের সাথে আছেন। আমি যদি আমার বাবা, আমি তাকে ছেড়ে দেব, আমি তাকে ছেড়ে দেব। আমি যদি আমার বাবার কাছে ক্ষমা চাই, তাহলে আমি তাকে ছেড়ে দেব। আমি জানি না যে, আমি তোমার জন্য প্রার্থনা করছি, আমি কি করতে পারি? কুত্তি।","‏ ‏حَدَّثَنَا ‏ ‏أُمَيَّةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَتَلَ ‏ ‏أَبَا جَهْلٍ ‏ ‏فَقَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي نَصَرَ عَبْدَهُ وَأَعَزَّ دِينَهُ ‏","","",""],[3807,3807,"","আমরা আমার নিজের ছেলেকে সরিয়ে নিতে চেষ্টা করেছি, কিন্তু আমরা একটি স্বপ্ন স্বপ্নের স্বপ্ন দেখতে পেরেছি। ঈশ্বরের দোহাই, সে বলেছিল আমরা জয়ী হয়েছি। ঈশ্বরের ইচ্ছা আছে। আমি বলেছি যে, বেনের রাজধানীকে সে করতে হবে... মনে রাখবে ওর সাথে আর ওর ফোন দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا فِي ‏ ‏غَزْوَةِ ‏ ‏بَدْرٍ ‏ ‏كُلُّ ثَلَاثَةٍ مِنَّا عَلَى بَعِيرٍ كَانَ ‏ ‏عَلِيٌّ ‏ ‏وَأَبُو لُبَابَةَ ‏ ‏زَمِيلَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا كَانَ ‏ ‏عُقْبَةُ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَا ارْكَبْ يَا رَسُولَ اللَّهِ حَتَّى نَمْشِيَ عَنْكَ فَيَقُولُ ‏ ‏مَا أَنْتُمَا بِأَقْوَى عَلَى الْمَشْيِ مِنِّي وَمَا أَنَا بِأَغْنَى عَنْ الْأَجْرِ مِنْكُمَا ‏ ‏حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏فَذَكَرَهُ بِمَعْنَاهُ وَإِسْنَادِهِ ‏","","",""],[3808,3808,"","কেন আমি ঈশ্বরের কাছে প্রার্থনা করব, যাতে তিনি স্বর্গে থাকবেন? সে তার প্রতারণার কারণে কিছুটা ব্যস্ত থাকবে, সে তিনগুণ অনুগ্রহ আর ভয় পেয়েছে অপরিচিতদের কষ্টের। কামনা, দুঃখ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أُسْرِيَ ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ وَإِلَيْهَا يَنْتَهِي مَا يُصْعَدُ بِهِ مِنْ الْأَرْضِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏وَمَا ‏ ‏يُعْرَجُ ‏ ‏بِهِ مِنْ الْأَرْضِ ‏ ‏فَيُقْبَضُ مِنْهَا وَإِلَيْهَا يَنْتَهِي مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا ‏ { ‏إِذْ ‏ ‏يَغْشَى ‏ ‏السِّدْرَةَ مَا ‏ ‏يَغْشَى ‏} ‏قَالَ فَرَاشٌ مِنْ ذَهَبٍ قَالَ ‏ ‏فَأُعْطِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ ‏ ‏خِلَالٍ ‏ ‏الصَّلَوَاتِ الْخَمْسَ وَخَوَاتِيمَ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏وَغُفِرَ لِمَنْ لَا يُشْرِكُ بِاللَّهِ عَزَّ وَجَلَّ مِنْ أُمَّتِهِ ‏ ‏الْمُقْحِمَاتُ ‏","","",""],[3809,3809,"","আমরা অনেকবার কথা বলেছি যে দিনের প্রান্তরে একজন শিকারীর মধ্যে আমি প্রথম পড়েছি, তিনি বলেছিলেন তিনি ঈশ্বর শান্তি বজায় রেখেছেন।","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏عَنْ ‏ ‏فُرَاتٍ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ الْجَرَّاحِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبِي ‏ ‏عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَسَمِعَهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّدَمُ تَوْبَةٌ ‏","","",""],[3810,3810,"","আমরা আমার বাবার সম্পর্কে অনেক কথা বলেছি কাপুরুষ হওয়ার জন্য, আল্লাহ আমাদের সাথে থাকতে পারেন যে তার দয়া দিয়ে দেওয়া হয়েছে আর তাকে দেখা যাবে আর ডিনার শেষ হয়ে গেল, আর তারপর আমি বললাম যে আমরা ঈশ্বরের অনুগ্রহ কামনা করি, ঈশ্বর এটা আর আমার আত্মা এটা দিয়েছেন, আমি বাসা তৈরি করেছিলাম এবং এরপর ঈশ্বরের কাছে তার নিজের ও আত্মসমর্পণের জন্য প্রার্থনা করতে আমাদের কাছে গিয়েছিলাম আর তারপর তিনি আরও বলেছিলেন । তুমি জিতেছ এবং তোমাকে ছেড়ে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحُبِسْنَا عَنْ صَلَاةِ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ فَاشْتَدَّ ذَلِكَ عَلَيَّ ثُمَّ قُلْتُ نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي سَبِيلِ اللَّهِ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ الصَّلَاةَ فَصَلَّى بِنَا الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى بِنَا الْعَصْرَ ثُمَّ أَقَامَ فَصَلَّى بِنَا الْمَغْرِبَ ثُمَّ أَقَامَ فَصَلَّى بِنَا الْعِشَاءَ ثُمَّ طَافَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏مَا عَلَى الْأَرْضِ ‏ ‏عِصَابَةٌ ‏ ‏يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ غَيْرُكُمْ ‏","","",""],[3811,3811,"","আমরা এক পুত্র সন্তানের কথা বলেছিলাম যে আমার শ্বশুরের দাস হতে যাচ্ছে। আমার বাবার সাহায্যের জন্য তার বাবা আছে। সে বলবে, ঈশ্বর তার প্রার্থনা শুনেছেন এবং বললেন তিনি চান যে তিনি যেন তার কাছে প্রার্থনা করেন। সে বলবে ঈশ্বর এসে গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُعَمَّرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبِي ‏ ‏عِنْدَ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَسَمِعَهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّدَمُ تَوْبَةٌ ‏","","",""],[3812,3812,"","ঈশ্বর হয়তো বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং ফিরে আসার আগে তিনি আত্মসমর্পণ করেছেন । এটা.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَوْمًا ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَرُعِدَ حَتَّى رُعِدَتْ ثِيَابُهُ ثُمَّ قَالَ نَحْوَ ذَا أَوْ شَبِيهًا بِذَا ‏","","",""],[3813,3813,"","আমরা বলেছিলাম, আমরা সিঁড়ি দিয়ে যাব না । ঈশ্বর আমাদের প্রভু ঈশ্বরের সঙ্গে আমাদের আশীর্বাদ করেছেন, যিনি বলেছিলেন যে, পিতা হলেন যিহোবা । ঈশ্বর তাঁর পিতার প্রতি অনুগত থাকেন এবং তিনি তা রক্ষা করবেন । আদ্দিশা বলেছিলেন যে, এটা ছিল একজন রাজা অথবা একটা ছেলের ঘনিষ্ঠ অংশ ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏وَحُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَأَبُو هَاشِمٍ ‏ ‏وَحَمَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏وَعَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏وَالْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا لَا نَدْرِي مَا نَقُولُ فِي الصَّلَاةِ نَقُولُ السَّلَامُ عَلَى اللَّهِ السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏السَّلَامُ عَلَى ‏ ‏مِيكَائِيلَ ‏ ‏قَالَ فَعَلَّمَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا جَلَسْتُمْ فِي رَكْعَتَيْنِ فَقُولُوا التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ ‏ ‏قَالَ ‏ ‏أَبُو وَائِلٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قُلْتَهَا أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَفِي الْأَرْضِ ‏ ‏وَقَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قُلْتَهَا أَصَابَتْ كُلَّ مَلَكٍ مُقَرَّبٍ أَوْ نَبِيٍّ مُرْسَلٍ أَوْ عَبْدٍ صَالِحٍ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[3814,3814,"","আল্লাহ তাঁর পতাকার জন্য প্রার্থনা করেছেন এবং তিনি থাকবেন না। ( যিশা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الشَّيْبَانِيِّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَرْنَا بِقَرْيَةِ نَمْلٍ فَأُحْرِقَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْبَغِي لِبَشَرٍ أَنْ يُعَذِّبَ بِعَذَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3815,3815,"","আমরা একটা ছেলের সবচেয়ে সুন্দর দর্শন সম্বন্ধে বলেছিলাম । দশ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ جَهَنَّمَ يَوْمَ الْقِيَامَةِ فَقَامَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ فَقَالَتْ يَا رَسُولَ اللَّهِ لِمَ نَحْنُ أَكْثَرُ أَهْلِ جَهَنَّمَ قَالَ لِأَنَّكُنَّ تُكْثِرْنَ ‏ ‏اللَّعْنَ ‏ ‏وَتَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏","","",""],[3816,3816,"","আমরা আমার বাবার এক সুখী ছেলের স্বপ্ন সম্বন্ধে আমাদের জীবনের সবচেয়ে ভাল দিক নিয়ে কথা বলেছি, যে তার সেবায় ফিরে আসবে। তার প্রভুর দিকে তাকিয়ে, কেউ না কেউ বলে তুমি কিভাবে এটা ভুলে গিয়েছিলে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَعَاهَدُوا ‏ ‏الْقُرْآنَ فَإِنَّهُ أَشَدُّ ‏ ‏تَفَصِّيًا ‏ ‏مِنْ صُدُورِ الرِّجَالِ مِنْ النَّعَمِ مِنْ ‏ ‏عُقُلِهَا ‏ ‏بِئْسَمَا لِأَحَدِهِمْ أَنْ يَقُولَ نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ ‏","","",""],[3817,3817,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন, যেন আমরা আপনাকে খুঁজে পাই । এটা ফেলে দাও আর কিছু একটা ফেলে দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏نَفَرٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ صَاحِبًا لَنَا اشْتَكَى ‏ ‏أَفَنَكْوِيهِ فَسَكَتَ سَاعَةً ثُمَّ قَالَ ‏ ‏إِنْ شِئْتُمْ فَاكْوُوهُ وَإِنْ شِئْتُمْ فَارْضِفُوهُ ‏","","",""],[3818,3818,"","আমরা কথা বলেছি আমার বাবা আমার বাবার ছেলেকে কীভাবে মিস করবে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন এই বলে যে খেলার জন্য হয়তো মিথ্যা বা বিচার হিসেবে লেখা আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْعَبْدَ لَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا أَوْ يَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا ‏","","",""],[3819,3819,"","ঈশ্বরের অনুগ্রহ তাকে আদেশ করে এবং আমরা যুবকদের আত্মসমর্পণ করেছি, যারা এক নয়, আমি প্রলুব্ধ হয়েছি। দর্শন এবং জয় করতে সক্ষম এবং তা করতে সক্ষম।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَبَابًا لَيْسَ لَنَا شَيْءٌ فَقَالَ ‏ ‏يَا مَعْشَرَ الشَّبَابِ مَنْ اسْتَطَاعَ مِنْكُمْ ‏ ‏الْبَاءَةَ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلْبَصَرِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّ الصَّوْمَ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[3820,3820,"","আমি আমার বাবার ছেলের টাকা পেয়ে কথা বলেছিলাম, আমি এমন একজন যাজককে খুঁজে বের করার চেষ্টা করছি যে আগামীকালের জন্য বলতে রাজি হবে, বাবা, সে যদি ঈশ্বরের কাছে যেতে পারত, তাহলে সে তার ছেলে হতো। স্বপ্ন, আমি দুই তলার নিচে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَابْنُ أَبِي زَائِدَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏الْأَشْعَثُ بْنُ قَيْسٍ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏وَهُوَ يَتَغَدَّى فَقَالَ يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏ادْنُ ‏ ‏لِلْغَدَاءِ قَالَ أَوَلَيْسَ ‏ ‏الْيَوْمُ عَاشُورَاءَ ‏ ‏قَالَ وَتَدْرِي مَا ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏إِنَّمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُهُ قَبْلَ أَنْ يَنْزِلَ رَمَضَانُ فَلَمَّا أُنْزِلَ رَمَضَانُ تُرِكَ ‏","","",""],[3821,3821,"","আমি তার কথা পড়ি এবং তাকে ধরে রাখার জন্য তিনি বলেছিলেন যে, আমাদের একটা ধনুক আছে । আমি আমার জীবনে ঈশ্বরের উদ্দেশ্য সম্বন্ধে আরও বেশি জানতে চাই । তারপর বলল, ঈশ্বর আমাদের বলেছেন, কৌশলটা কি না, তুমি দেখতে পাচ্ছ আমার কাছে জমজ ভাই আর আংটি নেই।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَمَعَنَا ‏ ‏زَيْدُ بْنُ حُدَيْرٍ ‏ ‏فَدَخَلَ عَلَيْنَا ‏ ‏خَبَّابٌ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَكُلُّ هَؤُلَاءِ يَقْرَأُ كَمَا تَقْرَأُ فَقَالَ إِنْ شِئْتَ أَمَرْتَ بَعْضَهُمْ فَقَرَأَ عَلَيْكَ قَالَ أَجَلْ فَقَالَ لِي اقْرَأْ فَقَالَ ‏ ‏ابْنُ حُدَيْرٍ ‏ ‏تَأْمُرُهُ يَقْرَأُ وَلَيْسَ بِأَقْرَئِنَا فَقَالَ أَمَا وَاللَّهِ ‏ ‏إِنْ شِئْتَ لَأُخْبِرَنَّكَ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقَوْمِكَ وَقَوْمِهِ قَالَ فَقَرَأْتُ خَمْسِينَ آيَةً مِنْ ‏ ‏مَرْيَمَ ‏ ‏فَقَالَ ‏ ‏خَبَّابٌ ‏ ‏أَحْسَنْتَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَا أَقْرَأُ شَيْئًا إِلَّا هُوَ قَرَأَهُ ثُمَّ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لِخَبَّابٍ ‏ ‏أَمَا آنَ لِهَذَا الْخَاتَمِ أَنْ ‏ ‏يُلْقَى قَالَ أَمَا إِنَّكَ لَا تَرَاهُ عَلَيَّ بَعْدَ الْيَوْمِ وَالْخَاتَمُ ذَهَبٌ ‏","","",""],[3822,3822,"","এর অর্থ হল, আপনার ঈশ্বর কেন ক্রয় করবেন, সেই সম্বন্ধে আপনার ধারণা অনেক বেশি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏رَفَعَهُ لَنَا فِي أَوَّلِ مَرَّةٍ ثُمَّ أَمْسَكَ عَنْهُ ‏ ‏يَعْنِي ‏ ‏شَرِيكٌ ‏ ‏قَالَ ‏ ‏الرِّبَا وَإِنْ كَثُرَ فَإِنَّ عَاقِبَتَهُ إِلَى قُلٍّ ‏","","",""],[3823,3823,"","আমরা কথা দিয়েছিলাম যে আমি কিভাবে কথা বলব তিনি ফিরে আসবেন আর তিনি বললেন যে ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন আর তিনি আত্মসমর্পণ করবেন যে, ঈশ্বর তাঁর জন্য কোন শাস্তি প্রদান করেননি। স্বপ্ন, আমি তোমার সহজাত প্রবৃত্তির কারণে বিরক্ত নই... ...আর আমার ভয় হচ্ছে যে তোমার এই ফুরানোর জন্য... ঈশ্বর হয়তো একজন বেশ্যার পুত্র, যিনি সেই কাজ সম্বন্ধে উল্লেখ করেছিলেন এবং বলেছিলেন যে, ব্যাট এবং যাও ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يُحَرِّمْ حُرْمَةً إِلَّا وَقَدْ عَلِمَ أَنَّهُ سَيَطَّلِعُهَا مِنْكُمْ مُطَّلِعٌ أَلَا وَإِنِّي مُمْسِكٌ ‏ ‏بِحُجَزِكُمْ ‏ ‏أَنْ تَهَافَتُوا فِي النَّارِ كَتَهَافُتِ الْفَرَاشِ وَالذُّبَابِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الْفَرَاشِ ‏ ‏أَوْ الذُّبَابِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ الْفَرَاشِ وَالذُّبَابِ ‏","","",""],[3824,3824,"","বাবা-এর কথা বলেছিলাম, যে কিনা কথা দিয়েছিল সে দেবী হতে যাচ্ছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর তার কামনা স্বীকার করতেও নিষেধ করেছেন, আর আমি তা পড়ে যেতে দেব। যতক্ষণ না আমি হাঁটব... ...আমি আমার চেয়েও শক্তিশালী।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ زَمِيلَهُ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏عَلِيٌّ ‏ ‏وَأَبُو لُبَابَةَ ‏ ‏فَإِذَا حَانَتْ ‏ ‏عُقْبَةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَا ارْكَبْ يَا رَسُولَ اللَّهِ حَتَّى نَمْشِيَ عَنْكَ فَيَقُولُ ‏ ‏مَا أَنْتُمَا بِأَقْوَى مِنِّي وَلَا أَنَا بِأَغْنَى عَنْ الْأَجْرِ مِنْكُمَا ‏","","",""],[3825,3825,"","ঈশ্বর বলেছিলেন যে, তিনি আপনাকে কাজ করতে বলেন এবং তিনি আমাকে বলেছিলেন যে, তিনি আমাকে এর জন্য প্রার্থনা করতে বলেছেন । পৌঁছে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ عَنْتَرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏عَلْقَمَةُ ‏ ‏وَالْأَسْوَدُ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ إِنَّهُ ‏ ‏سَيَلِيكُمْ أُمَرَاءُ يَشْتَغِلُونَ عَنْ وَقْتِ الصَّلَاةِ فَصَلُّوهَا لِوَقْتِهَا ثُمَّ ‏ ‏قَامَ فَصَلَّى بَيْنِي وَبَيْنَهُ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3826,3826,"","আমরা যেভাবে খরচ করেছি, সেই সব লোকেরা যারা ঈশ্বরের ছায়ার উপর বিশ্বাস রাখে না বলে... ...তারা বলেছে আমরা তার দিকে তাকাচ্ছি না. তার ছেলেকে বলা হয়েছে তুমি ঈশ্বরের দর্শনকে এক মহান ছায়ার সাথে ভাগাভাগি করো না","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ ‏ ‏بِظُلْمٍ ‏ } ‏قَالُوا يَا رَسُولَ اللَّهِ فَأَيُّنَا لَا يَظْلِمُ نَفْسَهُ قَالَ ‏ ‏لَيْسَ ذَاكَ هُوَ الشِّرْكَ أَلَمْ تَسْمَعُوا مَا قَالَ ‏ ‏لُقْمَانُ ‏ ‏لِابْنِهِ ‏ { ‏لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ ‏ ‏عَظِيمٌ ‏ }","","",""],[3827,3827,"","আমরা কথা বলেছি হয়তো কোন নাম লেখা আছে, ঈশ্বর তা জানেন অথবা সে না হয় তাকে হারাবে, না হলে সে তোমাকে ভুলে যাবে। প্রার্থনা করা এমন কিছু যা আমরা আগে প্রার্থনা করেছিলাম। তোমরা দুজন খুজে পেয়েছ, তারপর তোমরা দুজন খুজে পেয়েছ, তোমরা দুইজনকে খুঁজে পেয়েছ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِمَّا زَادَ وَإِمَّا نَقَصَ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏وَإِمَّا جَاءَ نِسْيَانُ ذَلِكَ مِنْ قِبَلِي ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ أَحَدَثَ فِي الصَّلَاةِ شَيْءٌ قَالَ وَمَا ذَاكَ قُلْنَا صَلَّيْتَ قَبْلُ كَذَا وَكَذَا قَالَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ أَنْسَى كَمَا تَنْسَوْنَ فَإِذَا نَسِيَ أَحَدُكُمْ فَلْيَسْجُدْ سَجْدَتَيْنِ ثُمَّ تَحَوَّلَ فَسَجَدَ سَجْدَتَيْنِ ‏","","",""],[3828,3828,"","আমরা একটা ছেলে সম্বন্ধে কথা বলেছিলাম, যার মুখ বড় হয়ে উঠেছে এবং তার মুখ সম্বন্ধে জানার চেষ্টা করেছি । লর্ড লর্ড লর্ড লর্ডের লর্ডের লর্ডের লর্ডের কাছে যাবে, তাকে ছেড়ে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عَبْدُ اللَّهِ ‏ ‏الشَّامَ ‏ ‏فَقَالَ لَهُ نَاسٌ مِنْ أَهْلِ ‏ ‏حِمْصَ ‏ ‏اقْرَأْ عَلَيْنَا فَقَرَأَ عَلَيْهِمْ سُورَةَ ‏ ‏يُوسُفَ ‏ ‏فَقَالَ رَجُلٌ مِنْ الْقَوْمِ وَاللَّهِ مَا هَكَذَا أُنْزِلَتْ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَيْحَكَ ‏ ‏وَاللَّهِ لَقَدْ ‏ ‏قَرَأْتُهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا فَقَالَ أَحْسَنْتَ فَبَيْنَا هُوَ يُرَاجِعُهُ إِذْ وَجَدَ مِنْهُ رِيحَ الْخَمْرِ فَقَالَ أَتَشْرَبُ ‏ ‏الرِّجْسَ ‏ ‏وَتُكَذِّبُ بِالْقُرْآنِ وَاللَّهِ لَا تُزَاوِلُنِي حَتَّى أَجْلِدَكَ فَجَلَدَهُ ‏ ‏الْحَدَّ ‏","","",""],[3829,3829,"","আমরা একটি ছেলের প্রতি করুণা দেখানোর কথা বলেছিলাম, যে কিনা কিনা দুই দিন আগে আমাকে ক্ষমা করে দিয়েছে এবং তোমাদের প্রতি দয়া করে ক্ষমা প্রার্থনা করেছে। তোমরা দু’বার দাঁড়িয়ে আছো, দুই বার, দুই ঘোড়া ছেড়ে নয়।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَمَّا رَأَى ‏ ‏عُثْمَانَ ‏ ‏صَلَّى ‏ ‏بِمِنًى ‏ ‏أَرْبَعَ رَكَعَاتٍ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَكْعَتَيْنِ ‏ ‏وَعُمَرَ ‏ ‏رَكْعَتَيْنِ لَيْتَ حَظِّي مِنْ أَرْبَعٍ رَكْعَتَانِ مُتَقَبَّلَتَانِ ‏","","",""],[3830,3830,"","আমরা বলেছিলাম, ডনকে কত ভালো কথা বলেছি। ঈশ্বর তার শীর্ষের উপরে আছেন এবং আমি যদি না করি তাহলে আমি তাকে কথা বলতে পারবো না। ঈশ্বরের দয়া তাকে আদেশ করে তাকে আদেশ দিয়েছে এবং সে তরুণ-পুরুষ হয়েছে। আমরা এমন কিছু বলতে চাই না, যার জন্য আমি বোকা হয়ে গেছি, আর যারা এটা দেখে বিস্মিত হতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏قَالَ دَخَلْنَا عَلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَعِنْدَهُ ‏ ‏عَلْقَمَةُ ‏ ‏وَالْأَسْوَدُ ‏ ‏فَحَدَّثَ حَدِيثًا لَا أُرَاهُ حَدَّثَهُ إِلَّا مِنْ أَجْلِي كُنْتُ أَحْدَثَ الْقَوْمِ سِنًّا قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَبَابٌ لَا نَجِدُ شَيْئًا فَقَالَ يَا مَعْشَرَ الشَّبَابِ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ ‏ ‏الْبَاءَةَ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلْبَصَرِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[3831,3831,"","ঈশ্বর বলেন যে, যারা এই কারণে অভিযুক্ত তাদের ওপর অভিশাপ নেমে এসেছে, তাদের জন্য ঈশ্বর কি কোনো অভিশাপ রয়েছে? দায়িত্বহীন সে সমাধান করে আর সে তার মুখে আসে নি, তুমি আমাকে আমার শরীর খুঁজে বের করার আদেশ দাও।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ ‏ ‏مِنْ ‏ ‏تِنْعَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا وُجِّهَتْ اللَّعْنَةُ تَوَجَّهَتْ إِلَى مَنْ ‏ ‏وُجِّهَتْ ‏ ‏إِلَيْهِ فَإِنْ وَجَدَتْ فِيهِ مَسْلَكًا ‏ ‏وَوَجَدَتْ سَبِيلًا ‏ ‏حَلَّتْ بِهِ وَإِلَّا جَاءَتْ إِلَى رَبِّهَا فَقَالَتْ يَا رَبِّ إِنَّ فُلَانًا وَجَّهَنِي إِلَى فُلَانٍ وَإِنِّي لَمْ أَجِدْ عَلَيْهِ سَبِيلًا وَلَمْ أَجِدْ فِيهِ مَسْلَكًا فَمَا تَأْمُرُنِي فَقَالَ ارْجِعِي مِنْ حَيْثُ جِئْتِ ‏","","",""],[3832,3832,"","আমরা বাবা সম্পর্কে কথা বলেছিলাম হয়তো ঈশ্বর বলেছেন, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করেছেন, দশ বছর বয়সী একজন মহিলা যিনি তার স্বপ্নে বিশ্বাস করেন, কিন্তু তিনি হবেন সেই হবে। যে লোক এই জন ্ য বেঁচে থাকবে সেটি তবে নিশ ্ চয় সাফল ্ য । একজন নারী যে তার জীবনের রাজা হবে, সে নয় যে বলেছে যে, আমরা যা বলি তার চেয়ে বেশি অপমানজনক হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ ‏ ‏تَصَدَّقْنَ وَلَوْ مِنْ حُلِيِّكُنَّ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ جَهَنَّمَ يَوْمَ الْقِيَامَةِ قَالَ فَقَامَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ فَقَالَتْ بِمَ نَحْنُ أَكْثَرُ أَهْلِ جَهَنَّمَ يَوْمَ الْقِيَامَةِ قَالَ فَقَالَ إِنَّكُنَّ تُكْثِرْنَ ‏ ‏اللَّعْنَ ‏ ‏وَتَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏","","",""],[3833,3833,"","আমরা বাবার দোহাইের সাথে কথা বলেছিলাম, যে ঈশ্বরকে না বলে... ...সে তোমাকে হত্যা করতে বলেছে...","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏وَقُلْتُ مَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏","","",""],[3834,3834,"","আমরা বাবার সাথে ঈশ্বরের দয়া নিয়ে ঝগড়ার কথা বলেছিলাম, তোমরা দুজন হলে তোমরা দুজন বেঁচে থাকতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يُحْزِنُهُ ‏","","",""],[3835,3835,"","আমরা একটা কুকুরের ছেলের সঙ্গে ঝগড়া করেছি, যে বলেছিল তার ব্যাপারে আমরা কথা বলেছি । তাদের নিজেদের ঋণ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يُحْزِنُهُ ‏","","",""],[3836,3836,"","আমরা একটা লড়াই আর একজন সাহসী বোনের ছেলে সম্পর্কে কথা বলেছি, যে একবার আমাদের একটা ছাগল নিয়ে কথা বলেছিল। আমরা তার জন্য অপেক্ষা করছি, যাতে আমরা বলতে পারি যে, তিনি তার কল্পনায় আনন্দ পাবেন। সে আমাদের নিজেদের ভয়ে আমাদেরকে গ্রাস করে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ بَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏نَنْتَظِرُهُ يَأْذَنُ لَنَا قَالَ فَجَاءَ ‏ ‏يَزِيدُ بْنُ مُعَاوِيَةَ النَّخَعِيُّ ‏ ‏فَدَخَلَ عَلَيْهِ فَقُلْنَا لَهُ أَعْلِمْهُ بِمَكَانِنَا فَدَخَلَ فَأَعْلَمَهُ فَلَمْ يَلْبَثْ أَنْ خَرَجَ إِلَيْنَا فَقَالَ إِنِّي لَأَعْلَمُ مَكَانَكُمْ فَأَدَعُكُمْ عَلَى ‏ ‏عَمْدٍ ‏ ‏مَخَافَةَ أَنْ أُمِلَّكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ فِي الْأَيَّامِ مَخَافَةَ السَّآمَةِ عَلَيْنَا ‏","","",""],[3837,3837,"","আমরা বাবার দোহাই দিয়ে বলছি, আমি শুধু তাদের পাশে দাঁড়িয়ে আছি, তোমার পরে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَلَأُنَازَعَنَّ أَقْوَامًا ثُمَّ لَأُغْلَبَنَّ عَلَيْهِمْ فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيُقَالُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[3838,3838,"","আমরা হয়তো আল্লাহ্‌র কাছে গিয়েছিলাম, তার নাম বলতে শুনেছি। আমি শুনেছি ঈশ্বরের নাম ছিল তার নাম এবং সে বলেছে যে, কে মারা গেছে এবং সে তোমাকে খেয়ে ফেলবে। আমি মারা যাব এবং এটা হবে না। ধন্যবাদ, শহরে এমন কিছু করার জন্য, যা তাকে আটকে রেখেছিল।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَةً وَقُلْتُ أُخْرَى سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ وَهُوَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏ ‏وَقُلْتُ ‏ ‏أَنَا ‏ ‏مَنْ مَاتَ وَهُوَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏ ‏وَوَافَقَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏خِلَافَ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏حَدَّثَنَاهُ ‏ ‏أَسْوَدُ ‏","","",""],[3839,3839,"","আমরা এক ভাইর কথা বলেছিলাম যে ঈশ্বর এসেছেন, আমি কখনোই ঈশ্বরের সমবেদনা পরিবর্তন করিনি, তোমার আত্মার প্রতি ভালোবাসার প্রতি ঈশ্বরের সমবেদনাকে আমি কখনো পরিবর্তন করিনি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَحَدٌ ‏ ‏أَغْيَرَ مِنْ اللَّهِ عَزَّ وَجَلَّ وَلِذَلِكَ حَرَّمَ ‏ ‏الْفَوَاحِشَ ‏ ‏وَمَا أَحَدٌ أَحَبَّ إِلَيْهِ الْمَدْحُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3840,3840,"","আমরা লর্ডের দিন সম্পর্কে কথা বলেছি, আমরা তার ক্ষতির কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَعَلْقَمَةُ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَقَالَ ‏ ‏إِذَا رَكَعَ أَحَدُكُمْ فَلْيُفْرِشْ ذِرَاعَيْهِ فَخِذَيْهِ فَكَأَنِّي أَنْظُرُ إِلَى اخْتِلَافِ أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[3841,3841,"","ঈশ্বর যা বলেছিলেন, ঈশ্বর তার চেয়ে আরও ভাল । গ্যাবজের ক্ষমতা দোটনারের অভিজাত পৌঁছানোর সঙ্গে সঙ্গে বাসাতে পৌঁছেছে আর এটা একটা ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً قَطُّ إِلَّا لِمِيقَاتِهَا إِلَّا صَلَاتَيْنِ صَلَاةَ الْمَغْرِبِ وَصَلَاةَ الْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏وَصَلَّى الْفَجْرَ يَوْمَئِذٍ قَبْلَ مِيقَاتِهَا ‏ ‏و قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏الْعِشَاءَيْنِ فَإِنَّهُ صَلَّاهُمَا ‏ ‏بِجَمْعٍ ‏ ‏جَمِيعًا ‏","","",""],[3842,3842,"","আমরা বাবার কথা বলেছিলাম, ঈশ্বর থেকে ভালো হওয়ার চেষ্টা করছে, গেমের সাথে সাথে সাথে সে বলেছে, তিন বার তার গর্ভের মধ্যে তার এতো ব্যস্ত থাকা সত্ত্বেও সে অনেক ব্যস্ত ছিল। অথবা তারপর একজোড়া হাঙ্গরও তার গর্ভের মধ্যে ভেঙে পড়েছিল। কথা বলে আমি বুঝতে পারিনি তাদের কেউ কেউ যদি চলে যায়, অন্যরা বলে আমরা ভাল কিছু শুনতে চাই, সে শুধু বলেছিল যে আমার ছেলে ঈশ্বরের কাছে প্রার্থনা করেছে আল্লাহ্‌র কাছে আত্মসমর্পণ করা এবং তিনি অবিবাহিত ছিলেন। আমি তোমাকে শুনতে চাই না। আমি বুঝতে পারছি না তুমি কিভাবে এটা বলবে এবং মনে করে তুমি এমন একজন হবে যে ভাবে তুমি নিজেকে ঈশ্বরের কাছে উৎসর্গ করবে। তুমিই হবে সেই লোক যে হবে সে হবে সেই হবে যে হবে সেই হবে সে হবে সেই হবে যারা হবে সেই হবে সেই হবে সেই হবে। যে ভয় পাবে, সে হবে সেই হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مُسْتَتِرًا بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَجَاءَ ثَلَاثَةُ ‏ ‏نَفَرٍ ‏ ‏كَثِيرٌ شَحْمُ بُطُونِهِمْ قَلِيلٌ فِقْهُ قُلُوبِهِمْ ‏ ‏قُرَشِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏ثَقَفِيَّانِ ‏ ‏أَوْ ‏ ‏ثَقَفِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏قُرَشِيَّانِ ‏ ‏فَتَكَلَّمُوا بِكَلَامٍ لَمْ أَفْهَمْهُ فَقَالَ بَعْضُهُمْ أَتَرَوْنَ أَنَّ اللَّهَ عَزَّ وَجَلَّ يَسْمَعُ كَلَامَنَا هَذَا فَقَالَ الْآخَرَانِ إِنَّا إِذَا رَفَعْنَا أَصْوَاتَنَا سَمِعَهُ وَإِذَا لَمْ نَرْفَعْ أَصْوَاتَنَا لَمْ يَسْمَعْهُ قَالَ وَقَالَ الْآخَرُ إِنْ سَمِعَ مِنْهُ شَيْئًا سَمِعَهُ كُلَّهُ قَالَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا كُنْتُمْ تَسْتَتِرُونَ أَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَذَلِكُمْ ظَنُّكُمْ الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُمْ مِنْ الْخَاسِرِينَ ‏}","","",""],[3843,3843,"","বাবা তার চেয়ে ভাল হওয়ার চেষ্টা করেছিলেন । আর শহরের কাছে যা ঋণী.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شِمْرِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ بْنِ سَعْدِ بْنِ الْأَخْرَمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتَّخِذُوا ‏ ‏الضَّيْعَةَ ‏ ‏فَتَرْغَبُوا فِي الدُّنْيَا ‏ ‏قَالَ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَبِرَاذَانَ ‏ ‏مَا ‏ ‏بِرَاذَانَ ‏ ‏وَبِالْمَدِينَةِ ‏ ‏مَا ‏ ‏بِالْمَدِينَةِ ‏","","",""],[3844,3844,"","আমরা বাবার সাথে যুদ্ধ করেছি, যে কিনা ঈশ্বরের অনুগ্রহের বিরুদ্ধে যুদ্ধ করেছে, যে কিনা ঈশ্বরের স্বপ্নের জয় লাভ করেছে এবং সে এক অবিশ্বাস্য বিষয়। মিথ্যা কথা, ঈশ্বর তা রক্ষা করতে হবে এবং আমি আপনাকে একটি মেয়েকে আমার আদর্শে যেতে নিষেধ করব। ঈশ্বর জয়ী হয়েছেন এবং যারা ঈশ্বরের প্রতিজ্ঞাগুলো কিনে নিয়েছে এবং তারপর তারা বলে যে আমরা বলতে চাই, ঈশ্বর তাদের তা করতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ فَقَالَ ‏ ‏الْأَشْعَثُ ‏ ‏فِيَّ وَاللَّهِ كَانَ ذَاكَ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏أَرْضٌ ‏ ‏فَجَحَدَنِي ‏ ‏فَقَدَّمْتُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَكَ ‏ ‏بَيِّنَةٌ ‏ ‏قُلْتُ لَا فَقَالَ لِلْيَهُودِيِّ احْلِفْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِذَنْ يَحْلِفَ فَيَذْهَبَ مَالِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ ‏ ‏بِعَهْدِ ‏ ‏اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[3845,3845,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি নিজেকে উৎসর্গ করেছেন যে, উপত্যকার লোকেদের কাছে যাওয়ার জন্য আমি সবচেয়ে ভাল অগ্নিময় অগ্নি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ صُبَيْحٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَشَدِّ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ الْمُصَوِّرِينَ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏أَشَدِّ النَّاسِ ‏","","",""],[3846,3846,"","বাবা যখন মারা যান, তখন আমরা বাবা - মায়ের সঙ্গে কথা বলার চেষ্টা করি । ( গীতসংহিতা ১১৯: ১৬৫) একজন কুমারী হওয়ার বিষয়ে ভাববাদী বলেছিলেন, যিনি কিছু সময়ের জন্য একটা মামলা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنَامُ مُسْتَلْقِيًا حَتَّى يَنْفُخَ ثُمَّ يَقُومُ فَيُصَلِّي وَلَا يَتَوَضَّأُ ‏ ‏حَدَّثَنَاه ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏فُضَيْلٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[3847,3847,"","ঈশ্বর তা রক্ষা করতে চান এবং আমি এমন কিছু করতে চাই, যা রক্ষা পাবে, তা আমাকে মেরে ফেলতে হবে । ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَةٍ لَهُ فَقَالَ ‏ ‏ائْتِنِي بِشَيْءٍ ‏ ‏أَسْتَنْجِي بِهِ وَلَا تُقْرِبْنِي حَائِلًا وَلَا رَجِيعًا ثُمَّ أَتَيْتُهُ بِمَاءٍ فَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى فَحَنَا ثُمَّ طَبَّقَ يَدَيْهِ حِينَ رَكَعَ وَجَعَلَهُمَا بَيْنَ فَخِذَيْهِ ‏","","",""],[3848,3848,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং এমন একজন ব্যক্তিকে আত্মসমর্পণ করতে বলেছেন, যিনি তার উত্তরাধিকারী হবেন বলে বলা হবে । ( মথি ২৪: ১৪) আর তারপরই সে খুবই রেগে যাবে, তোমার লোকেরা সেটা বলে দিয়েছিল সেটা একটা রহস্য ।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجُلٍ نَسْتَأْذِنُهُ أَنْ نَكْوِيَهُ فَسَكَتَ ثُمَّ سَأَلْنَاهُ مَرَّةً أُخْرَى فَسَكَتَ ثُمَّ سَأَلْنَاهُ الثَّالِثَةَ فَقَالَ ‏ ‏ارْضِفُوهُ إِنْ شِئْتُمْ كَأَنَّهُ غَضْبَانُ ‏","","",""],[3849,3849,"","আমরা দুটো উপায়ে কথা বলেছি, যা আমরা আগে কখনো করেছি, ঈশ্বর নিশ্চয়ই বলেছিলেন আমরা ঈশ্বরের অনুগ্রহে ঈশ্বরের মঙ্গলভাব দেখেছি, আর তিনি তার অধিকার ছেড়ে দেবেন ঈশ্বরের দয়ায়, বড় আর বড় যা তুমি কর।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَنَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي كُلِّ رَفْعٍ وَوَضْعٍ وَقِيَامٍ وَقُعُودٍ وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يَبْدُوَ جَانِبُ خَدِّهِ وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَفْعَلَانِ ذَلِكَ ‏","","",""],[3850,3850,"","আমরা দিনের দুই দিনের কথা বলেছি, আমরা একে অপরকে খুন করার চেষ্টা করেছি। ঈশ্বরের দোহাই, ঈশ্বরের দোহাই, ঈশ্বরের দোহাই। ঈশ্বরের দোহাই, ঈশ্বরের দোহাই, খোদার দোহাই!","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ذَكَرَهُ وَلَكِنْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى الْخَلَاءَ وَقَالَ ‏ ‏ائْتِنِي بِثَلَاثَةِ أَحْجَارٍ فَالْتَمَسْتُ فَوَجَدْتُ حَجَرَيْنِ وَلَمْ أَجِدْ الثَّالِثَ فَأَتَيْتُهُ بِحَجَرَيْنِ ‏ ‏وَرَوْثَةٍ ‏ ‏فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ إِنَّهَا ‏ ‏رِكْسٌ ‏","","",""],[3851,3851,"","আমরা আমার বাবার কথা বলেছিলাম, কিন্তু সে আমার সাথে কথা বলেছিল, সে ঈশ্বরের ইচ্ছা বিষাক্ত করেছে, আর সে তার রিং রিং দিয়ে তার রিং রিং গুলো সে দিয়ে দিয়েছে... ঈশ্বরের কাছে করা অঙ্গীকার তাঁর শক্তি এবং তাঁর কল্পনাকে নষ্ট করেছে। তার ছেলেরা বলে যে, আল্লাহ আমার শক্তি দিয়ে আমাকে মাফ করে দিয়েছেন, তারা জানে না যে তিনি হয়ত বলেছেন। ঈশ্বর আমাকে বলেছেন যে, সে এমন হবে না যে হবে সে হবে হবে সেই হবে একজন যে হবে সেই হবে। সে-ই হবে সেই ব্যক্তি যে হবে হবে, সে হবে একজন যে হবে হবে। সে তার মুখ মুছে ফেলবে, তাকে টেনে নেবে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَائِمَ ‏ ‏حُنَيْنٍ ‏ ‏بِالْجِعِرَّانَةِ ‏ ‏قَالَ فَازْدَحَمُوا عَلَيْهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ عَبْدًا مِنْ عِبَادِ اللَّهِ بَعَثَهُ اللَّهُ عَزَّ وَجَلَّ إِلَى قَوْمِهِ فَكَذَّبُوهُ ‏ ‏وَشَجُّوهُ ‏ ‏فَجَعَلَ يَمْسَحُ الدَّمَ عَنْ جَبِينِهِ وَيَقُولُ رَبِّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لَا يَعْلَمُونَ قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ جَبْهَتَهُ يَحْكِي الرَّجُلَ ‏","","",""],[3852,3852,"","আমরা আমার বাবার ছেলে সম্পর্কে কথা বলেছি আর সে আমাদের ঈশ্বর সম্পর্কে জানতে দেবে না। আমার ছেলে খুশি ছিল তিন বছর আগে আমি এমন ছিলাম না যে আমার ছেলে ছিল একজন পেশাদার এবং ভুলে গেছি। শেষ পর্যন্ত সে বলেছিল তার কাছে টাকা ছিল কিন্তু সে বলেছিল যে তার কাছে ঈশ্বরের সেরাটা ছিল। আমি হয়তো আমার সাথে জড়িত হয়ে যেতে চাই। ( ১ করিন্থীয় ১৫: ৩৩) বোকারা বলেছিল যে, কোনোকিছু যেন অন্ধ না হয় বরং সত্যের আত্মা দ্বারা প্রভাবিত হয় অথবা লোকেদের মৃত্যু ঘটায় ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏كُنْتُ لَا أُحْبَسُ عَنْ ثَلَاثٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَنَسِيَ ‏ ‏عَمْرٌو ‏ ‏وَاحِدَةً وَنَسِيتُ أَنَا أُخْرَى وَبَقِيَتْ هَذِهِ ‏ ‏عَنْ ‏ ‏النَّجْوَى ‏ ‏عَنْ كَذَا وَعَنْ كَذَا قَالَ فَأَتَيْتُهُ وَعِنْدَهُ ‏ ‏مَالِكُ بْنُ مُرَارَةَ الرَّهَاوِيُّ ‏ ‏قَالَ فَأَدْرَكْتُ مِنْ آخِرِ حَدِيثِهِ وَهُوَ يَقُولُ يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ قَدْ قُسِمَ لِي مِنْ الْجَمَالِ مَا ‏ ‏تَرَى فَمَا أُحِبُّ أَنَّ أَحَدًا مِنْ النَّاسِ فَضَلَنِي ‏ ‏بِشِرَاكَيْنِ ‏ ‏فَمَا فَوْقَهُمَا أَفَلَيْسَ ذَلِكَ هُوَ الْبَغْيَ قَالَ ‏ ‏لَيْسَ ذَلِكَ ‏ ‏بِالْبَغْيِ ‏ ‏وَلَكِنَّ ‏ ‏الْبَغْيَ ‏ ‏مَنْ سَفِهَ الْحَقَّ ‏ ‏أَوْ بَطِرَ الْحَقَّ ‏ ‏وَغَمَطَ ‏ ‏النَّاسَ ‏","","",""],[3853,3853,"","আমি আমার বাবার স্বপ্নের কথা বলেছি, ঈশ্বর আমাকে বললেন, ঘুমের জন্য রাত জেগে ওঠা পর্যন্ত আমি বলতে পারি যে শয়তানের কান বা কানের মধ্যে একটা মানুষ আছে।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ نَامَ لَيْلَةً حَتَّى أَصْبَحَ قَالَ ‏ ‏ذَاكَ رَجُلٌ بَالَ الشَّيْطَانُ فِي أُذُنِهِ ‏ ‏أَوْ أُذُنَيْهِ ‏","","",""],[3854,3854,"","আমরা আমার বাবার একটা অনুগত ভাবনা নিয়ে কথা বলেছি যে তিনি হয়তো ঈশ্বরের নাম ছিলেন। আমি ভেবেছিলাম, ঈশ্বর এটা দিয়েছেন এবং তিনি তা অর্জন করেছেন। কেরামের ঘৃণা আমাদের।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مِمَّا يُذَكِّرُ كُلَّ يَوْمِ الْخَمِيسِ فَقِيلَ لَهُ لَوَدِدْنَا أَنَّكَ ذَكَّرْتَنَا كُلَّ يَوْمٍ قَالَ إِنِّي أَكْرَهُ أَنْ أُمِلَّكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ كَرَاهِيَةَ ‏ ‏السَّآمَةِ ‏ ‏عَلَيْنَا ‏","","",""],[3855,3855,"","আমরা যখন ঘরে ঘরে প্রচার করতাম, তখন আমরা আমাদের পরিবারের সঙ্গে দেখা করতে যেতাম । তিনি ঘোড়া বিক্রি করে ঘোড়া বিক্রি করে ঘোড়া দিয়ে দৌড়ে দৌড়ে দৌড়ে দৌড়ে দৌড়ে তাকে ফেলে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏حَتَّى انْتَهَى إِلَى ‏ ‏جَمْرَةِ الْعَقَبَةِ ‏ ‏فَقَالَ نَاوِلْنِي أَحْجَارًا قَالَ فَنَاوَلْتُهُ سَبْعَةَ أَحْجَارٍ فَقَالَ لِي خُذْ ‏ ‏بِزِمَامِ ‏ ‏النَّاقَةِ قَالَ ثُمَّ عَادَ إِلَيْهَا فَرَمَى بِهَا مِنْ ‏ ‏بَطْنِ الْوَادِي ‏ ‏بِسَبْعِ حَصَيَاتٍ وَهُوَ رَاكِبٌ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ وَقَالَ ‏ ‏اللَّهُمَّ اجْعَلْهُ حَجًّا مَبْرُورًا وَذَنْبًا مَغْفُورًا ثُمَّ قَالَ هَاهُنَا كَانَ يَقُومُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3856,3856,"","আমরা বলেছিলাম যে কীভাবে বাবা আর ঈশ্বরের পরে একজন মানুষ... ( ১ করিন্থীয় ১০: ৩৪) তাই, একজন ব্যক্তি যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন তিনি তাঁর কাছে প্রার্থনা করেছিলেন এবং সিদ্ধান্ত নেবেন যে, তিনি দুটো জায়গায় থাকবেন ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَقَالَ إِنِّي قَرَأْتُ الْبَارِحَةَ ‏ ‏الْمُفَصَّلَ ‏ ‏فِي رَكْعَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَثْرًا ‏ ‏كَنَثْرِ ‏ ‏الدَّقَلِ ‏ ‏وَهَذًّا ‏ ‏كَهَذِّ ‏ ‏الشِّعْرِ إِنِّي لَأَعْلَمُ ‏ ‏النَّظَائِرَ ‏ ‏الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرُنُ ‏ ‏بَيْنَهُنَّ سُورَتَيْنِ فِي رَكْعَةٍ ‏","","",""],[3857,3857,"","আমরা তর্কের কথা বলেছি... ...আমাদের জন্য দুইটা জাহাজ তৈরি করেছি... ...যেন আমরা একটা কুঠরীর সাথে ফাঁসিতে আটকা না পড়ি। সেই প্রতিবেশীরা বলেছিল যে, তাকে হত্যা করা হয়েছে, মনে হয় তাকে মেরে ফেলা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَارٍ فَأُنْزِلَتْ عَلَيْهِ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏فَجَعَلْنَا ‏ ‏نَتَلَقَّاهَا مِنْهُ فَخَرَجَتْ حَيَّةٌ مِنْ جَانِبِ ‏ ‏الْغَارِ ‏ ‏فَقَالَ ‏ ‏اقْتُلُوهَا فَتَبَادَرْنَاهَا فَسَبَقَتْنَا فَقَالَ إِنَّهَا وُقِيَتْ شَرَّكُمْ كَمَا وُقِيتُمْ شَرَّهَا ‏","","",""],[3858,3858,"","আমরা বাবার সঙ্গে একত্রে মিলিত হওয়ার চেষ্টা করেছিলাম । সে বলেছিল সে আমাদের কথা শুনেছে যে খোদা এসেছে আর আমি প্রার্থনা করছি আর তার জন্য পরীক্ষা করে বলি, সালাম ঈশ্বরের সবচেয়ে মূল্যবান জিনিস হিসেবে সেবা করেছে যদি সে কখনো বলে থাকে তাহলে তাকে তার জীবন বাঁচানোর জন্য ডাকা হবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جَلَسْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ قَبْلَ عِبَادِهِ السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏السَّلَامُ عَلَى ‏ ‏مِيكَائِيلَ ‏ ‏السَّلَامُ عَلَى فُلَانٍ السَّلَامُ عَلَى فُلَانٍ قَالَ فَسَمِعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا جَلَسَ أَحَدُكُمْ ‏ ‏فِي الصَّلَاةِ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِذَا قَالَهَا أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ بَعْدُ مِنْ الدُّعَاءِ مَا شَاءَ ‏","","",""],[3859,3859,"","সেই অতিথি ও আত্মার আত্মা এবং আপনার বাকি জীবন দেখা করার সুযোগ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ ‏ ‏الثَّيِّبُ ‏ ‏الزَّانِي وَالنَّفْسُ بِالنَّفْسِ وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ ‏","","",""],[3860,3860,"","আমরা আশা করছি আমাদের কাছে দুটো তলোয়ার আছে, যেটা বেনের সাথে চলছে আর ঈশ্বর বলে যে সে ভুলে গেছে, ঈশ্বর তাকে আশীর্বাদ করুন আর সে হবে প্রভুর প্রভু। ঈশ্বরকে জিজ্ঞেস করতে হবে, যে পাপ করেছে, সে কি আশা করতে পারে যে আমি শেষ পর্যন্ত অন্য জায়গায় আশাবাদী। আমার বাবা বেন পাস করেছেন, তিনি ঈশ্বরের দোহাইতে গর্ভবতী।","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ فِتَنٌ وَأُمُورٌ تُنْكِرُونَهَا قَالُوا يَا رَسُولَ اللَّهِ فَمَا تَأْمُرُنَا قَالَ ‏ ‏تُؤَدُّونَ الْحَقَّ الَّذِي عَلَيْكُمْ وَتَسْأَلُونَ اللَّهَ عَزَّ وَجَلَّ الَّذِي لَكُمْ ‏ ‏قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏وَجَدْتُ فِي مَوْضِعٍ آخَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[3861,3861,"","আমরা তার কাজ করার জন্য তার জন্য জীবন্ত এবং দৃষ্টির কথা বলেছিলাম. আমরা ঈশ্বরের অনুগ্রহে ছিলাম, প্রার্থনা করি তাকে জীবিত অবস্থায় উদ্ধার করা হয়েছে. লর্ড তার কাছে প্রার্থনা করেছিলেন এবং তার কাছে প্রার্থনা করেছিলেন আত্মসমর্পণ এবং তোমার প্রাণকে হত্যা করে... ...যা তোমাকে বলা হয়েছিল আর পশুর বজ্রপাতের সাথে জড়িত ছিল.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْغَارِ فَخَرَجَتْ عَلَيْنَا حَيَّةٌ فَتَبَادَرْنَاهَا فَسَبَقَتْنَا فَدَخَلَتْ الْجُحْرَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وُقِيَتْ شَرَّكُمْ كَمَا وُقِيتُمْ شَرَّهَا ‏ ‏قَالَ ‏ ‏وَزَادَ ‏ ‏الْأَعْمَشُ ‏ ‏فِي الْحَدِيثِ قَالَ كُنَّا ‏ ‏نَتَلَقَّاهَا مِنْ ‏ ‏فِيهِ وَهِيَ رَطْبَةٌ ‏","","",""],[3862,3862,"","আমরা বাবা মা'র জন্য যুদ্ধ সম্পর্কে কথা বলেছি, আল্লাহকে এমন এক অভিযানে উদ্ধার করতে হয়েছে যা হয়তো তার নিজের আর সবচেয়ে খারাপ উপায়ের মধ্যে দিয়ে মুছে ফেলা হয়েছে। তারা তাকে মেরে ফেলতে সমর্থ হয়েছিল, আমরা তাকে খুন করেছিলাম, বলেছিলাম ঈশ্বর এসেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَارٍ وَقَدْ أُنْزِلَتْ عَلَيْهِ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏قَالَ فَنَحْنُ نَأْخُذُهَا مِنْ ‏ ‏فِيهِ رَطْبَةً إِذْ خَرَجَتْ عَلَيْنَا حَيَّةٌ فَقَالَ ‏ ‏اقْتُلُوهَا ‏ ‏فَابْتَدَرْنَاهَا ‏ ‏لِنَقْتُلَهَا فَسَبَقَتْنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَاهَا اللَّهُ شَرَّكُمْ كَمَا وَقَاكُمْ شَرَّهَا ‏","","",""],[3863,3863,"","আমরা আমার বাবার কথা বলেছিলাম একজন ধর্মনিষ্ঠ যাজকের দ্বারা গুলি করা হয়েছে, আমি গাড়ি চালিয়ে গাড়ি চালিয়ে যেতে পারি এই বলে যে এটা কোন মূল্য না। ঈশ্বর আকুতিকে আত্মসমর্পণ করেছেন এবং আমরা শয়তানের কাছে আহ্বান জানিয়েছে যেন আমরা না বলি সে বলেছে সে কত বলেছে, কিন্তু আমরা তোমার ভাগ্যের বিরুদ্ধে লড়াই করবো আর তোমার ইচ্ছার ক্ষমা করব, আমি তার মুখ আর তার গোপনীয়তা নিয়ে চুরি করে ফেলব।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مُخَارِقٍ الْأَحْمَسِيِّ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏لَقَدْ شَهِدْتُ مِنْ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏قَالَ غَيْرُهُ ‏ ‏مَشْهَدًا لَأَنْ أَكُونَ أَنَا صَاحِبَهُ أَحَبُّ إِلَيَّ مِمَّا عُدِلَ بِهِ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَدْعُو عَلَى الْمُشْرِكِينَ فَقَالَ لَا نَقُولُ لَكَ كَمَا قَالَ قَوْمُ ‏ ‏مُوسَى ‏ { ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ ‏} ‏وَلَكِنْ نُقَاتِلُ عَنْ يَمِينِكَ وَعَنْ شِمَالِكَ وَمِنْ بَيْنِ يَدَيْكَ وَمِنْ خَلْفِكَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَقَ وَجْهُهُ وَسَرَّهُ ذَاكَ ‏","","",""],[3864,3864,"","আমরা লর্ডের সাথে কথা বলেছি যে তিনি এটা শুনতে ভালো লাগবে। আর আমি তাকে বড় করেছি, তোমার জন্য যে সে খুবই খারাপ আর অবিশ্বাস্য। শুধু একটা ছেলে ছেলেই আছে। ঈশ্বর নরকে জয় করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُرَّةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ لِي ‏ ‏شُعْبَةُ ‏ ‏وَرَفَعَهُ وَلَا أَرْفَعُهُ لَكَ ‏ ‏يَقُولُ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَمَنْ يُرِدْ فِيهِ ‏ ‏بِإِلْحَادٍ ‏ ‏بِظُلْمٍ ‏} ‏قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا هَمَّ فِيهِ ‏ ‏بِإِلْحَادٍ ‏ ‏وَهُوَ ‏ ‏بِعَدَنِ أَبْيَنَ ‏ ‏لَأَذَاقَهُ اللَّهُ عَزَّ وَجَلَّ عَذَابًا أَلِيمًا ‏","","",""],[3865,3865,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছি যা ঘটেছে তার ব্যাপারে। আল্লাহ হয়ত তার কাছে প্রার্থনা করেছেন এবং তিনি তার চোখ বা পঞ্চমটি উৎসর্গ করবেন এবং তারপর মসজিদটি খুঁজে পাবেন। বিশ্বাস করতে হবে যে এটা বেশি অথবা কম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏أَوْ الْعَصْرَ ‏ ‏خَمْسًا ثُمَّ سَجَدَ سَجْدَتَيْنِ فَقَالَ هَذِهِ السَّجْدَتَانِ لِمَنْ ظَنَّ مِنْكُمْ أَنَّهُ زَادَ أَوْ نَقَصَ ‏","","",""],[3866,3866,"","আমরা আমার বাবার ছেলের কথা বলেছিলাম আমার বাবার বাবার বাবার সাথে একজন কনেকন্যার কম্পনের জন্য, যাকে আমার বাবা আর মায়ের জন্য মনোনীত করা হয়েছিল। যে বোন কখনো থাকতে পারবে না, তাকে বলব যে সে হয়ত ভুল করেছে আর সে তোমাকে কখনই কেড়ে নিতে পারবে না। সে বলল একটা ছেলে আবার ফিরে আসবে। পবিত্র পিতার অর্ধেক পুত্র এবং একমাত্র যে বেছে নিতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُزَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏أَنَّ ‏ ‏الْأَشْعَرِيَّ ‏ ‏أُتِيَ فِي ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ لِأَبٍ وَأُمٍّ قَالَ فَجَعَلَ ‏ ‏لِلِابْنَةِ النِّصْفَ وَلِلْأُخْتِ مَا بَقِيَ وَلَمْ يَجْعَلْ لِابْنَةِ ‏ ‏الِابْنِ شَيْئًا قَالَ فَأَتَوْا ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَأَخْبَرُوهُ قَالَ فَقَالَ لَقَدْ ضَلَلْتُ إِذَنْ وَمَا أَنَا مِنْ الْمُهْتَدِينَ إِنْ أَخَذْتُ بِقَوْلِهِ وَتَرَكْتُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏لِلِابْنَةِ النِّصْفُ وَلِابْنَةِ ‏ ‏الِابْنِ السُّدُسُ وَمَا بَقِيَ لِلْأُخْتِ ‏","","",""],[3867,3867,"","ঈশ্বরের আশীর্বাদ যখন তাঁর কাছে প্রার্থনা করেছিল এবং তুমি যখন গর্ভের পক্ষে ছিলে, তখন তিনি হাঁটু গেড়ে আত্মসমর্পণ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَأَنَّمَا كَانَ جُلُوسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّكْعَتَيْنِ عَلَى ‏ ‏الرَّضْفِ ‏","","",""],[3868,3868,"","আমরা বাবার বাবার ভালবাসার কথা বলেছি... ...কিন্তু ঈশ্বরের কাছে আছে, সে যদি আমার সাথে থাকে তাহলে সে তোমার কাছে আত্মসমর্পণ করবে, আর তিন সেকেন্ডেই তোমাকে ধরা হবে, আর আমি তোমার কাছে থাকবো। মনে হচ্ছে তুমি খুশি হবে, তোমার আত্মসমর্পণের আগে, আর তুমি আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كُنْتَ فِي الصَّلَاةِ فَشَكَكْتَ فِي ثَلَاثٍ وَأَرْبَعٍ وَأَكْثَرُ ظَنِّكَ عَلَى أَرْبَعٍ تَشَهَّدْتَ ثُمَّ سَجَدْتَ سَجْدَتَيْنِ وَأَنْتَ جَالِسٌ قَبْلَ أَنْ تُسَلِّمَ ثُمَّ تَشَهَّدْتَ أَيْضًا ثُمَّ سَلَّمْتَ ‏","","",""],[3869,3869,"","আমরা শুধু মাত্র কিছু কাজ করে ফেলেছি যখন আমরা ঈশ্বর চলে গেলে একটি হাত খেলা করার চেষ্টা করেছি. আপনি একটি গোল যে আপনি একটি মেয়ে ছিল যে আপনি একটি গোল ছিল যে আপনি একটি গোল ছিল যে আপনি একটি গোল ছিল যে আপনি একটি গোল ছিল যে আপনি ছিল যে আপনি একটি গোল যত দ্রুত সম্ভব আমি পারবো, তারপর দুটো খুঁজে বের করবে, তারপর দেখবে তুমি খুজে পাবে কিনা আর তারপর তুমি পাবে। তারপর সে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِذَا شَكَكْتَ فِي صَلَاتِكَ وَأَنْتَ جَالِسٌ فَلَمْ تَدْرِ ثَلَاثًا صَلَّيْتَ أَمْ أَرْبَعًا فَإِنْ كَانَ أَكْبَرُ ظَنِّكَ أَنَّكَ صَلَّيْتَ ثَلَاثًا فَقُمْ فَارْكَعْ رَكْعَةً ثُمَّ سَلِّمْ ثُمَّ اسْجُدْ سَجْدَتَيْنِ ثُمَّ تَشَهَّدْ ثُمَّ سَلِّمْ وَإِنْ كَانَ أَكْبَرُ ظَنِّكَ أَنَّكَ صَلَّيْتَ أَرْبَعًا فَسَلِّمْ ثُمَّ اسْجُدْ سَجْدَتَيْنِ ثُمَّ تَشَهَّدْ ثُمَّ سَلِّمْ ‏","","",""],[3870,3870,"","আমরা সেই অন্যায়কারীকে আরও ভাল একজন সুরক্ষার জন্য চেষ্টা করেছিলাম । ঠিক, তাই বাবা বলেছে, আগুনটা এসেছে দুটো শব্দ দিয়ে, সে বলেছে সে একটা মিথ্যুক। আমি মাত্র একবার এসেছি, কিন্তু আমি প্রথম বারের মত আছি যখন থেকে আমি প্রথম এসেছি। তিনি আমার বাবার কাছে গিয়েছিলেন কিন্তু ঈশ্বর তাকে নিয়ে চিন্তা করেছিলেন । আমার বাবা আমার সঙ্গে কথা বলেছিলেন, একজন কোপারনিকার বাবা যিনি আমার বাবার সঙ্গে ছিলেন, তিনি যা ছিলেন, সেই বিষয়ে ভয় পেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُحَمَّدٍ ‏ ‏مَوْلًى ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَدَّمَ ثَلَاثَةً لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏كَانُوا لَهُ حِصْنًا حَصِينًا مِنْ النَّارِ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏قَدَّمْتُ اثْنَيْنِ قَالَ وَاثْنَيْنِ فَقَالَ ‏ ‏أُبَيُّ بْنُ كَعْبٍ أَبُو الْمُنْذِرِ ‏ ‏سَيِّدُ الْقُرَّاءِ قَدَّمْتُ وَاحِدًا قَالَ وَوَاحِدٌ وَلَكِنْ ذَاكَ فِي أَوَّلِ ‏ ‏صَدْمَةٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ ‏ ‏مَوْلًى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَقَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏لَمْ أُقَدِّمْ إِلَّا اثْنَيْنِ ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَاهُ ‏ ‏يَزِيدُ ‏ ‏أَيْضًا ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏مَضَى لِي اثْنَانِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْعَوَّامُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو مُحَمَّدٍ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏خَالَفَا ‏ ‏هُشَيْمًا ‏ ‏فَقَالَا ‏ ‏أَبُو مُحَمَّدٍ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏","","",""],[3871,3871,"","আমরা স্যারেনের একটা ছেলেকে হারানোর কথা বলেছিলাম যে সে তোমার টাকা ভুলে গেছে। আমি মনে করি তুমি তাকে হত্যা করতে ভুলে গেছ। এটা একটা লজ্জা যে, সে ধরা পড়েছে। তাকে তোমার টাকা ভুলে যেতে দেখ.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏شَهِدَ جِنَازَةَ رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏فَأَظْهَرُوا ‏ ‏الِاسْتِغْفَارَ فَلَمْ يُنْكِرْ ذَلِكَ ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فِي حَدِيثِهِ وَأَدْخَلُوهُ مِنْ قِبَلِ رِجْلِ الْقَبْرِ ‏ ‏وَقَالَ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّةً إِنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مَاتَ ‏ ‏بِالْبَصْرَةِ ‏ ‏فَشَهِدَهُ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏فَأَظْهَرُوا لَهُ ‏ ‏الِاسْتِغْفَارَ ‏","","",""],[3872,3872,"","তার লোকেরা মারা যাওয়ার পর আমরা তাদের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏مَعَ ‏ ‏أَنَسٍ ‏ ‏فِي جِنَازَةٍ ‏ ‏فَأَمَرَ بِالْمَيِّتِ فَسُلَّ مِنْ قِبَلِ ‏ ‏رِجْلَيْهِ ‏","","",""],[3873,3873,"","আমরা ভুলে যাওয়ার কথা বলেছিলাম... ...স্যারেন বলেছিল যে, মানুষ গোপন জিনিসটা ভালো ছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَنَسٌ ‏ ‏أَحْسَنَ النَّاسِ صَلَاةً فِي السَّفَرِ وَالْحَضَرِ ‏","","",""],[3874,3874,"","আমরা সলিনের কথা বলেছিলাম... ...আমি তার টাকা ভুলে যাবো, দেখ তাকে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَسْتَشْرِفُ لِشَيْءٍ وَهُوَ فِي الصَّلَاةِ يَنْظُرُ إِلَيْهِ ‏","","",""],[3875,3875,"","আমরা আমার মুখ দিয়ে কথা বলেছি যে ছেলে আমাকে রক্ষা করতে চায়। আমার সাথে লড়াই করতে চায় এমন আবেগের লড়াই করার কথা, যা আমরা যে আবেগে তৈরি করেছি তার একটা রীতিতে পরিণত হয়েছে, আমি বলতে চাচ্ছি, সে আমাকে নিয়ে কথা বলতে চায়, তোমার মুখ থেকে লড়াই করবে না, ঈশ্বর ওর কাছে প্রার্থনা করেছেন আর আমি তার গোপনীয়তার চেয়ে বেশি কিছু উদ্ধার করবো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ بْنُ يَزِيدَ ‏ ‏قَالَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏لَا يَجْعَلْ أَحَدُكُمْ لِلشَّيْطَانِ مِنْ نَفْسِهِ جُزْءًا لَا يَرَى إِلَّا أَنَّ حَتْمًا عَلَيْهِ أَنْ يَنْصَرِفَ عَنْ يَمِينِهِ فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرُ انْصِرَافِهِ عَنْ يَسَارِهِ ‏","","",""],[3876,3876,"","আমরা দুই বছর ধরে আমার ছেলে এবং তার আত্মীয়দের জন্য সমস্যার কথা বলেছি, ঈশ্বর ভুলে গেছেন সে কিভাবে ছিল আর কিভাবে ভুলে গিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏بِئْسَمَا لِأَحَدِكُمْ أَنْ يَقُولَ نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ ‏","","",""],[3877,3877,"","আমরা দুটো জাহাজের কথা বলেছিলাম, আর ঈশ্বর বলেছিলেন, \"বাবা.\" আমি আকাশে যা করেছি তা নিয়ে যাচ্ছি... ...তুমি আমাকে নিয়ে যাওনি আর আমাকে নিয়ে যেতে বলোনি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏وَسُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ إِنْ أَحْسَنْتَ لَمْ تُؤَاخَذْ وَإِنْ أَسَأْتَ فِي الْإِسْلَامِ أُخِذْتَ بِالْأَوَّلِ وَالْآخِرِ ‏","","",""],[3878,3878,"","আমরা দুই বছরের ভালোবাসার এক সুখী ছেলের কথা বলেছি যার মুক্তি পেয়েছে। আমি তার কাছে প্রার্থনা করবো এবং বলতে চাই, ঈশ্বরের অনুগ্রহ আছে। এবং তারপর সে ব্যথাটা বলবে যে সে এমনকি তাকে খুঁজে পাবার স্বপ্ন দেখে, \"তারা তাকে হত্যা করার অধিকার কি করবে\"। আর তুমি তাকে বিশ্বাস কর।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏وَسُلَيْمَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ يَهُودِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ عَلَى إِصْبَعٍ وَالْأَرَضِينَ عَلَى إِصْبَعٍ وَالْجِبَالَ عَلَى إِصْبَعٍ وَالْخَلَائِقَ عَلَى إِصْبَعٍ وَالشَّجَرَ عَلَى إِصْبَعٍ ثُمَّ يَقُولُ أَنَا الْمَلِكُ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏وَقَالَ ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ ‏} ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَقَالَ ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ عِيَاضٍ ‏ ‏تَعَجُّبًا وَتَصْدِيقًا لَهُ ‏","","",""],[3879,3879,"","আমরা বাবার সবচেয়ে ভাল বাজির কথা বলেছিলাম... ...ঈশ্বর তাকে আমার সকল প্রধানের কাছে শিক্ষা দিয়েছেন, আর আমার প্রভু ও তার সাথে যারা আছে তাদের কাছে হস্তান্তর করেছেন। ভবিষ্যদ্বাণী এবং যারা তাদের ওপর বিশ্বাস রাখে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ ‏ ‏وُلَاةٌ ‏ ‏مِنْ النَّبِيِّينَ وَإِنَّ ‏ ‏وَلِيِّي ‏ ‏مِنْهُمْ أَبِي وَخَلِيلُ رَبِّي عَزَّ وَجَلَّ ثُمَّ قَرَأَ ‏ { ‏إِنَّ أَوْلَى النَّاسِ ‏ ‏بِإِبْرَاهِيمَ ‏ ‏لَلَّذِينَ اتَّبَعُوهُ وَهَذَا النَّبِيُّ وَالَّذِينَ آمَنُوا ‏}","","",""],[3880,3880,"","ঈশ্বর গর্ভের সঙ্গে শপথ করে শূককীটকে বড় বড় বড় বড় বড় বড়ি করার প্রতিজ্ঞা করেছেন । এটা বললে, তাকে আর এগিয়ে যেতে হবে না এবং তাকে ডাউনলোড করতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏حَدَّثَنِي ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏اسْتَبْطَنَ ‏ ‏الْوَادِيَ ‏ ‏فَجَعَلَ ‏ ‏الْجَمْرَةَ ‏ ‏عَنْ حَاجِبِهِ الْأَيْمَنِ وَاسْتَقْبَلَ ‏ ‏الْبَيْتَ ‏ ‏ثُمَّ رَمَاهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ ‏ ‏دُبُرَ ‏ ‏كُلِّ حَصَاةٍ ثُمَّ قَالَ هَذَا وَالَّذِي لَا إِلَهَ غَيْرُهُ مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3881,3881,"","আমরা শুধু খুশি হয়েছি এবং আমরা কিভাবে বেঁচে থাকতে পারি সে ব্যাপারে কথা বলেছি। সত্যি বলতে কি, আমি আর আমার প্রতিবেশীকে আরেকটু পেতে চেষ্টা করছি না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏الْمَعْنَى عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُرَّةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏آكِلُ الرِّبَا ‏ ‏وَمُوكِلُهُ وَشَاهِدَاهُ وَكَاتِبُهُ إِذَا عَلِمُوا بِهِ ‏ ‏وَالْوَاشِمَةُ ‏ ‏وَالْمُسْتَوْشِمَةُ ‏ ‏لِلْحُسْنِ وَلَاوِي ‏ ‏الصَّدَقَةِ ‏ ‏وَالْمُرْتَدُّ أَعْرَابِيًّا بَعْدَ هِجْرَتِهِ مَلْعُونُونَ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[3882,3882,"","আমরা জীবন্ত এবং এই সম্পর্কে উত্তেজিত সম্পর্কে কথা বলেছি, ঈশ্বরের ইচ্ছা হল তার কাছে প্রার্থনা করা এবং তিনি আত্মসমর্পণ করবেন এবং তিনি তাকে হত্যা করবেন এবং তিনি বলবেন আপনি একজন তার সাথে আবদ্ধ থাকবে. রাত দুই সপ্তাহ, তারপর তোমার মত উজ্জ্বল হতে হবে, সে তার সকল কথা দিয়ে তাকে পরাজিত করবে, সে এটা করবে, যদিও সে মনে করে সে তাই করবে, সে মনে করে যে সে ভয় পাবে। এটা করো, যদি আমার বাবার ইচ্ছা হয়, আমি তার বাবা-মা'র কাছে পাগল হয়ে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏قَالَ ‏ ‏إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ فِي أَرْبَعِينَ يَوْمًا ‏ ‏أَوْ قَالَ أَرْبَعِينَ لَيْلَةً ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏لَيْلَةً ‏ ‏ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ ثُمَّ يَكُونُ ‏ ‏مُضْغَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يُرْسِلُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ الْمَلَكَ بِأَرْبَعِ كَلِمَاتٍ عَمَلُهُ وَأَجَلُهُ وَرِزْقُهُ وَشَقِيٌّ أَوْ سَعِيدٌ ثُمَّ يُنْفَخُ فِيهِ الرُّوحُ فَوَالَّذِي لَا إِلَهَ غَيْرُهُ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ فَيَكُونُ مِنْ أَهْلِهَا وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَكُونُ مِنْ أَهْلِهَا ‏","","",""],[3883,3883,"","আমরা দুজন তলোয়ার নিয়ে যুদ্ধ করার কথা বলেছিলাম, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর সে বলবে তুমি একটা অন্যায় আত্মা মারবে যদি তার ছেলে থাকে!","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُقْتَلُ نَفْسٌ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏كِفْلٌ ‏ ‏مِنْ دَمِهَا ذَاكَ أَنَّهُ أَوَّلُ مَنْ ‏ ‏سَنَّ ‏ ‏الْقَتْلَ ‏","","",""],[3884,3884,"","আমরা একজন বোনের সাথে কথা বলেছি যে কিনা হয়তো ঈশ্বরের দোহাইে পড়ে গেছে, তাদের কেউই বেঁচে থাকতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يَحْزُنُهُ ‏","","",""],[3885,3885,"","ঈশ্বর তাকে আদেশ দিয়েছেন, যেন তিনি তাকে প্রভুকে এবং তার প্রভুর কাছে যেতে বলেন । হে প্রভু, সেই বছর যা বলল, \"ঈশ্বর, ঈশ্বর, এটাই আমাকে বলেছে।\"","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَصَابَ ‏ ‏مِنْ امْرَأَةٍ قُبْلَةً فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ كَفَّارَتِهَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ ‏ ‏يُذْهِبْنَ ‏ ‏السَّيِّئَاتِ ‏} ‏قَالَ يَا رَسُولَ اللَّهِ أَلِي هَذِهِ قَالَ لِمَنْ عَمِلَ مِنْ أُمَّتِي ‏","","",""],[3886,3886,"","আমরা বাবার সাথে কথা বলেছিলাম হয়তো আল্লাহ্‌র কথা বলতে পারে আর আমরা কথা বলেছি যে মানুষ মিথ্যা বলবে যখন ঈশ্বর মিথ্যা কথা বলবেন আর ঐ মানুষটা হতে হবে যে লেখার অধিকার আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَّ الرَّجُلَ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا وَأَنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا ‏","","",""],[3887,3887,"","আমার বাবার সাথে যমজের কথা বলেছিলাম যে তার ছেলে পরের বইয়ে ফিরে গিয়েছিল আর লড়াই করতে চেষ্টা করেছিল, সে আর ফিরে আসেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏مَنْ اشْتَرَى ‏ ‏مُحَفَّلَةً ‏ ‏وَرُبَّمَا قَالَ شَاةً ‏ ‏مُحَفَّلَةً ‏ ‏فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏","","",""],[3888,3888,"","শেষ সংবাদ তার কাছে প্রার্থনা করেছে এবং তারা চোখের পানি উৎসর্গ করেছে।","‏ ‏وَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏تَلَقِّي ‏ ‏الْبُيُوعِ ‏","","",""],[3889,3889,"","ঈশ্বর এমন এক বিচার থেকে নিজেকে পৃথক করেছেন, যা সেই লোকেদের পরিচালনা দেয়, যারা জীবনের জীবনের অধিকারী নয় । দুনিয়ার জীবনের জীবনের জীবনের জীবন, ঈশ্বর তাকে এই ভুলকে বলতে দিবেন না যে আমি তাকে নরকে ফেলে দেব। দুটো জরিমানা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ مَرَّةً أَوْ مَرَّتَيْنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ حَكَمٍ يَحْكُمُ بَيْنَ النَّاسِ إِلَّا حُبِسَ يَوْمَ الْقِيَامَةِ وَمَلَكٌ آخِذٌ بِقَفَاهُ حَتَّى يَقِفَهُ عَلَى جَهَنَّمَ ثُمَّ يَرْفَعَ رَأْسَهُ إِلَى اللَّهِ عَزَّ وَجَلَّ فَإِنْ قَالَ الْخَطَأَ أَلْقَاهُ فِي جَهَنَّمَ يَهْوِي أَرْبَعِينَ خَرِيفًا ‏","","",""],[3890,3890,"","আমরা দুটো জাহাজের কথা বলেছিলাম যেগুলো আমার নাম থেকে মানুষে লড়াই করার আগ পর্যন্ত মোটা হয়ে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَذْهَبُ الدُّنْيَا ‏ ‏أَوْ لَا ‏ ‏تَنْقَضِي الدُّنْيَا ‏ ‏حَتَّى يَمْلِكَ ‏ ‏الْعَرَبَ ‏ ‏رَجُلٌ مِنْ أَهْلِ بَيْتِي ‏ ‏يُوَاطِئُ ‏ ‏اسْمُهُ اسْمِي ‏","","",""],[3891,3891,"","তিনি আমাকে বলেছিলেন যে, ইতিহাস সম্বন্ধে আমরা যে আবেগ নিয়ে কথা বলেছি, সেই বিষয়ে আমি এক সুখী ছেলে সম্বন্ধে পড়েছি । ফিরে এসে তাকে বলব আমি জিতব কিনা তা দেখার চেষ্টা করব। তার স্ত্রী বন্ধু আছে এবং তার কল্পনার নারীত্ব আছে। সে বলছে যে তিনি নিজেকে আত্মসমর্পণ করেছেন। সে আপনাকে যুদ্ধের সাক্ষী করেছে, আমরা তোমাকে কখনো দেখিনি, আর সার্জন হল দুজন লোক।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏فَسُئِلَ عَنْ رَجُلٍ تَزَوَّجَ امْرَأَةً ‏ ‏وَلَمْ يَكُنْ سَمَّى لَهَا صَدَاقًا فَمَاتَ قَبْلَ أَنْ يَدْخُلَ بِهَا فَلَمْ يَقُلْ فِيهَا شَيْئًا فَرَجَعُوا ثُمَّ أَتَوْهُ فَسَأَلُوهُ فَقَالَ سَأَقُولُ فِيهَا بِجَهْدِ رَأْيِي فَإِنْ أَصَبْتُ فَاللَّهُ عَزَّ وَجَلَّ يُوَفِّقُنِي لِذَلِكَ وَإِنْ أَخْطَأْتُ فَهُوَ مِنِّي ‏ ‏لَهَا ‏ ‏صَدَاقُ ‏ ‏نِسَائِهَا وَلَهَا الْمِيرَاثُ وَعَلَيْهَا ‏ ‏الْعِدَّةُ ‏ ‏فَقَامَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَشْجَعَ ‏ ‏فَقَالَ أَشْهَدُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَضَى بِذَلِكَ قَالَ ‏ ‏هَلُمَّ ‏ ‏مَنْ يَشْهَدُ لَكَ بِذَلِكَ فَشَهِدَ ‏ ‏أَبُو الْجَرَّاحِ ‏ ‏بِذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏الْمَعْنَى إِلَّا أَنَّهُ قَالَ فِي ‏ ‏بَرْوَعَ بِنْتِ وَاشِقٍ ‏ ‏فَقَالَ ‏ ‏هَلُمَّ ‏ ‏شَاهِدَاكَ عَلَى هَذَا فَشَهِدَ ‏ ‏أَبُو سِنَانٍ ‏ ‏وَالْجَرَّاحُ ‏ ‏رَجُلَانِ مِنْ ‏ ‏أَشْجَعَ ‏","","",""],[3892,3892,"","ঈশ্বরের দোহাইর জন্য আমার মুখ দিয়ে বেঁচে থাকার কথা, তাকে প্রার্থনা করতে হয়েছে আমরা তার প্রভুর কাছে প্রার্থনা করতে বলেছি, তারা ঈশ্বরের কাছে প্রার্থনা করবে। তারা বলবে না যে সিঁড়ির উপর দিয়ে যেতে হবে, এটা সালম। কিন্তু এটা হল সেলম। যদি আমি বসে থাকি, আমি বলি, সালামের কাছে ক্ষমা আছে এবং সবচেয়ে দুঃখের সাথে কাজ করছে। সব জিনিস বিষে আক্রান্ত এবং অসুস্থ হয়ে যাচ্ছে, আমি নিশ্চিত যে এটা এর মূল্য নয়। এটা বলে ভান করে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنِي ‏ ‏شَقِيقٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جَلَسْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ مِنْ عِبَادِهِ السَّلَامُ عَلَى فُلَانٍ وَفُلَانٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُوا السَّلَامُ عَلَى اللَّهِ فَإِنَّ اللَّهَ هُوَ السَّلَامُ وَلَكِنْ إِذَا جَلَسَ أَحَدُكُمْ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِنَّكُمْ إِذَا قُلْتُمْ ذَلِكَ أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ بَيْنَ السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ لِيَتَخَيَّرْ أَحَدُكُمْ مِنْ الدُّعَاءِ أَعْجَبَهُ إِلَيْهِ فَلْيَدْعُ بِهِ ‏","","",""],[3893,3893,"","আমরা কথা বলেছি আর বাবা আমার সাথে এমন ব্যবহার করেছে যেন আমরা আমার বাবার সাথে বাস করছি। লর্ড তার কাছে প্রার্থনা করেছে এবং আমি যা করতে পারি তার কাছে তাকে আত্মসমর্পণ করব এবং তারপর সে তা করতে বাধ্য হবে। নিজের বক্তব্যের উদ্দেশ্য নিয়ে আপনার ছেলেকে হত্যা করে... ...আর তারপর সে যা বলেছে তা হল, সে আমাকে বলেছে তোমার প্রতিবেশীকে শাস্তি দেয়া হবে। তার বইয়ে যারা যাবে না। ঈশ্বরের সাথে কথা বলার জন্য শেষ কথা বলা... ...আর কে তোমার কাজ করবে?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَيُّ الذَّنْبِ أَكْبَرُ قَالَ أَنْ تَجْعَلَ لِلَّهِ ‏ ‏نِدًّا ‏ ‏وَهُوَ خَلَقَكَ قَالَ ثُمَّ أَيٌّ قَالَ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ مِنْ أَجْلِ أَنْ يَطْعَمَ مَعَكَ قَالَ ثُمَّ أَيٌّ قَالَ ثُمَّ أَنْ تُزَانِيَ ‏ ‏بِحَلِيلَةِ ‏ ‏جَارِكَ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَصْدِيقَ ذَلِكَ فِي كِتَابِهِ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ ‏ ‏أَثَامًا ‏ }","","",""],[3894,3894,"","আমরা আমার বাবা আর ঈশ্বরের কথা বলেছি, বাবা আর বাবা কি বলেছে, আমরা কথা বলেছি বাবা আর বাবা কী বলতে পারে, আমি যা শুনেছি তা নিয়ে। ঈশ্বর, আমি যা বলছি তা নিয়ে কথা বলেছি। আমি যা বলছি তা নিয়ে আমি এখন বলি। আমি এখন আমার বাবা এবং বাবা-মা, আমি তাকে বলছি। আমি কি করব? আমি জানি না, আমি কি করব? কী ঘটেছিল, সেই বিষয়ে যিনি যথেষ্ট ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ فَقَالَ مَنْ أَحْسَنَ فِي الْإِسْلَامِ لَمْ يُؤَاخَذْ بِمَا عَمِلَ فِي الْجَاهِلِيَّةِ وَمَنْ أَسَاءَ فِي الْإِسْلَامِ أُخِذَ بِالْأَوَّلِ وَالْآخِرِ ‏","","",""],[3895,3895,"","আমরা আমার বাবার কথা বলেছি, উজ্জ্বল ছেলেটা বলেছিল আমরা ভবিষ্যৎ খুঁজে পেয়েছি। অশুভ কথা হলো যদি মূল্যবোধ আকাশ থেকে বিশ্বাসঘাতকের মত সরিয়ে নেয়া হয়, দরিদ্র ও পাপের নাম, বলতে গেলে আমি তোমাকে আল্লাহ্‌র নামে উল্লেখ করেছিলাম. ঈশ্বর আমি জানি, ঈশ্বর তার মালিক এবং তার প্রভুর কাছে কখনো তার স্বপ্নের স্বপ্ন দেখেন না। ষড়যন্ত্রকারীরা তাকে যেতে দিচ্ছে না। তিনি বলছেন যে তিনি এক বছর ধরে এই খাবার খেতে দিয়েছেন। তার হাতের কসম, ক্ষুধার্তদের ধোঁয়া বলে, \"আমরা হয়ত জানতে পারি যে সে মারা গেছে।\" তারা ঈশ্বরের দোহাইে ফিরে গেছে। এটাকে বলে অন্ধকার হওয়ার আগে \"ফারট\" বলা যায়, আমাদের ঘুমাতে যেতে হবে এবং বলতে হবে যে এটা কতটা ভালো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏بَيْنَا رَجُلٌ يُحَدِّثُ فِي الْمَسْجِدِ الْأَعْظَمِ قَالَ إِذَا كَانَ يَوْمُ الْقِيَامَةِ نَزَلَ دُخَانٌ مِنْ السَّمَاءِ فَأَخَذَ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ وَأَخَذَ الْمُؤْمِنِينَ مِنْهُ كَهَيْئَةِ الزُّكَامِ قَالَ ‏ ‏مَسْرُوقٌ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ وَكَانَ مُتَّكِئًا فَاسْتَوَى جَالِسًا فَأَنْشَأَ يُحَدِّثُ فَقَالَ ‏ ‏يَا أَيُّهَا النَّاسُ مَنْ سُئِلَ مِنْكُمْ عَنْ عِلْمٍ هُوَ عِنْدَهُ فَلْيَقُلْ بِهِ فَإِنْ لَمْ يَكُنْ عِنْدَهُ فَلْيَقُلْ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ الْعِلْمِ أَنْ تَقُولَ لِمَا لَا تَعْلَمُ اللَّهُ أَعْلَمُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ لِنَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنْ الْمُتَكَلِّفِينَ ‏} ‏إِنَّ ‏ ‏قُرَيْشًا ‏ ‏لَمَّا غَلَبُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَعْصَوْا عَلَيْهِ قَالَ ‏ ‏اللَّهُمَّ أَعِنِّي بِسَبْعٍ كَسَبْعِ ‏ ‏يُوسُفَ ‏ ‏قَالَ فَأَخَذَتْهُمْ سَنَةٌ أَكَلُوا فِيهَا الْعِظَامَ وَالْمَيْتَةَ مِنْ الْجَهْدِ حَتَّى جَعَلَ أَحَدُهُمْ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ كَهَيْئَةِ الدُّخَانِ مِنْ الْجُوعِ فَقَالُوا ‏ { ‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ ‏} ‏قَالَ فَقِيلَ لَهُ إِنَّا إِنْ كَشَفْنَا عَنْهُمْ عَادُوا فَدَعَا رَبَّهُ فَكَشَفَ عَنْهُمْ فَعَادُوا فَانْتَقَمَ اللَّهُ مِنْهُمْ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَذَلِكَ قَوْلُهُ تَعَالَى ‏ { ‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏ ‏إِلَى قَوْلِهِ ‏ ‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ ‏} ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏فِي حَدِيثِهِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَلَوْ كَانَ يَوْمَ الْقِيَامَةِ مَا كَشَفَ عَنْهُمْ ‏","","",""],[3896,3896,"","আমি বাবার কাছ থেকে অনেক বেশি কিছু শুনেছি, ঈশ্বর আদেশ দিয়েছেন তাকে আত্মসমর্পণ করতে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مِنْ مُذَّكِرٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏هَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ }","","",""],[3897,3897,"","আমরা আমার বাবা আর লর্ডের কথা বলেছি যে তিনি শান্তি স্থাপন করেছেন। যদি তুমি অল্প কিছু ছিলে, তোমরা তাদের দুজনের থেকে বাঁচতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ ‏ ‏دُونَ وَاحِدٍ فَإِنَّ ذَلِكَ يُحْزِنُهُ ‏","","",""],[3898,3898,"","আমরা আমার বাবা আর বাবার কথা বলেছি, আল্লাহ তার জন্য প্রার্থনা করেছেন আর তিনি আত্মসমর্পণ করবেন আর তার হৃদয়ের খারাপ অবস্থা বিচার করবেন। কাপুরুষরা আর বলছে খোদা আমার শক্তি ক্ষমা করে দেবেন তারা তা জানতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَحْكِي نَبِيًّا مِنْ الْأَنْبِيَاءِ ضَرَبَهُ قَوْمُهُ فَهُوَ ‏ ‏يَنْضَحُ ‏ ‏الدَّمَ ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏يَمْسَحُ الدَّمَ عَنْ جَبِينِهِ ‏ ‏وَيَقُولُ رَبِّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لَا يَعْلَمُونَ ‏","","",""],[3899,3899,"","আমরা আমার বাবা আর তার বাবার কথা বলেছি, ঈশ্বর তাকে হাত বাড়িয়ে বলতে বলেছেন আর মিথ্যা বলতে হবে না। ঈশ্বর মিথ্যা বলেছেন এবং বলেছেন যে ঈশ্বর তাকে ছেড়ে চলে গেছেন। তিনি একটা ভুল করার জন্য হুমকি দেন আর সত্যের বিরুদ্ধে লড়াই করার জন্য তিনি চান ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَالْفُجُورَ يَهْدِي إِلَى النَّارِ وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا وَقَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالصِّدْقِ فَإِنَّ الصِّدْقَ يَهْدِي إِلَى ‏ ‏الْبِرِّ ‏ ‏وَإِنَّ ‏ ‏الْبِرَّ ‏ ‏يَهْدِي إِلَى الْجَنَّةِ وَإِنَّهُ ‏ ‏يَعْنِي الرَّجُلَ ‏ ‏لَيَصْدُقُ ‏ ‏وَيَتَحَرَّى ‏ ‏الصِّدْقَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ ‏ ‏وَيَتَحَرَّى ‏ ‏الصِّدْقَ ‏","","",""],[3900,3900,"","আমরা কথা বলেছি এবং তার থেকে ঈশ্বরের অনুগ্রহের কথা শুনতে চাই। সে কখনোই দুই লোকের কাছে ঈশ্বরের কাছে আসবে না। সে হলে তাকে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَآخَرُ آتَاهُ اللَّهُ حِكْمَةً فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا ‏","","",""],[3901,3901,"","আমরা আমার বাবার কথা বলেছি কিন্তু নাবিকদের দ্বারা আমরা বেঁচে আছি। খোদা তার জন্য প্রার্থনা করেছেন এবং অন্ত্যেষ্টিক্রিয়ার মিছিলে গিয়ে বলেন কি হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏مَا دُونَ ‏ ‏الْخَبَبِ ‏ ‏الْجِنَازَةُ مَتْبُوعَةٌ وَلَيْسَتْ بِتَابِعٍ ‏","","",""],[3902,3902,"","আমরা একবারের জন্য সেক্সের কথা বলেছি, গড দাবি করেছে, আর আমাদের গব এর বাসা থেকে উদ্ধার করে নি... মুখ.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ ‏ ‏شَقَّ ‏ ‏الْجُيُوبَ ‏ ‏وَلَطَمَ الْخُدُودَ وَدَعَا ‏ ‏بِدَعْوَى ‏ ‏الْجَاهِلِيَّةِ ‏","","",""],[3903,3903,"","আমরা অনেকবার কথা বলেছি, যে ছেলে একটা ছেলের সাথে আমাদের ঝগড়া করেছে, আমরা ঈশ্বরের কাছে প্রার্থনা করছি না, সে এটা ত্যাগ করবে, যে তোমাকে সাহায্য করতে পারে। দৃষ্টি, আমি বাইরে যেতে বের হচ্ছি এবং যে এটা করতে পারে না তার শেষ শব্দ.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ الشَّبَابِ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ ‏ ‏الْبَاءَةَ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلْبَصَرِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[3904,3904,"","আমরা বাবার অমর পুত্র সম্পর্কে কথা বলেছি... ...যে হয়তো বলেছিল আমরা প্রভুর কাছে প্রার্থনা করছি. যে ব ্ যক ্ তি উপুড় হয়ে যাওয়ার মত এবং যে নিজেকে একজন বলেই সে ব ্ যক ্ তি , সে ব ্ যতীত অন ্ য কেউ একজন হতে পারে না । ঈশ্বর হয়তো আমার সমস্যার সমাধানের রান্নাকে উপেক্ষা করতে পারেন না ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَابٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي ‏ ‏فَنَهَانَا ثُمَّ رَخَّصَ لَنَا فِي أَنْ نَنْكِحَ الْمَرْأَةَ بِالثَّوْبِ إِلَى ‏ ‏الْأَجَلِ ‏ ‏ثُمَّ قَرَأَ ‏ ‏عَبْدُ اللَّهِ ‏ { ‏لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ ‏}","","",""],[3905,3905,"","আমরা একে অপরের সাথে কথা বলেছি আমার বাবার ভালবাসার প্রতি ঈর্ষার কারণে আমার বাবার ভালবাসাকে ঈর্ষার কারণ হিসেবে। আমি এটা করেছি, কিন্তু এটা শেষ হয়ে গেছে এবং আমি তাকে বলছি যে এটা শেষ পর্যন্ত শেষ হয়ে গেছে। আমি বলেছিলাম, আমার বাবার প্রতি ঈর্ষা করার স্বপ্নের কারণে আমি আমার বাবার প্রতি ঈর্ষা প্রকাশ করছি। কিন্তু আমি এটা করেছি। আমি বলছি, এটা আমার বাবার ভালবাসার জন্য অনেক কিছু একটা আছে। কিন্তু আমি বলছি, আমি এটা করতে চাই না যে, আমি আমার বাবার প্রতি ঈর্ষা করি। আমি এটা করতে চাই না। কিন্তু আমি যদি আমার বাবার প্রতি ঈর্ষা করি, আমি এটা করতে চাই, আমি এটা করতে চাই, আমি জানি যে, আমি এটা করতে চাই। আমি জানি না। আমি জানি যে, আমি এটা আমার বাবার প্রতি ঈর্ষা করি, আমি এটা একটা বিষয় যে আমি যা বলছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর আমি যখন পরাজিত হব না, তখন তিনি পরিতৃপ্তি থেকে বঞ্চিত হবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْهِلَالِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا كَانَ فِي سَفَرٍ فَوَلَدَتْ امْرَأَتُهُ فَاحْتُبِسَ لَبَنُهَا فَجَعَلَ يَمُصُّهُ وَيَمُجُّهُ فَدَخَلَ حَلْقَهُ فَأَتَى ‏ ‏أَبَا مُوسَى ‏ ‏فَقَالَ حُرِّمَتْ عَلَيْكَ قَالَ فَأَتَى ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَسَأَلَهُ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَرِّمُ مِنْ الرَّضَاعِ إِلَّا مَا أَنْبَتَ اللَّحْمَ وَأَنْشَزَ الْعَظْمَ ‏","","",""],[3906,3906,"","আমরা অনেক বছর ধরে আমার বাবার পাপের জন্য আমার বাবার প্রয়োজন কথা বলেছি। ব্যাপ্টিস্টটা তাকে ব্যবহার করে তাকে ক্ষমা করে আমরা তাকে হারাতে পারব। আমি নিশ্চিত তার কোন ঈশ্বর নেই এবং আমি নিশ্চিত সে হয়ত তার উপর কব্জা করতে পারে। আমি নিশ্চিত যে সে হয়ত তার বাবার পাপের জন্য তাকে ছেড়ে দেবে। কিন্তু আমি নিশ্চিত যে সে হয়ত তার কোন কিছু করতে পারবে। কিন্তু আমি নিশ্চিত যে, আমি তাকে ক্ষমা করতে পারি। আমি জানি না যে, আমি তাকে ক্ষমা করতে হবে। আমি জানি, আমি যদি আমি সত্যিই তাকে ক্ষমা করতে পারি। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি তোমার কাছে এটা একটা নতুন উপায় আছে। কিন্তু আমি যদি তুমি জানো না, আমি এটা করতে পারি। আমি তোমার জন্য এটা একটা বিষয় হবে। কিন্তু আমি জানি যে, আমি জানি, আমি তোমার জন্য অনেক বড় হয়েছি। তারা আবার এটা পড়ে গেছে। তারা একগুঁয়েমি না হয়ে মারা গেছে। সাহদ্দাহ বলেছেন, শেষ কথা আমি আমার বাবার গোপন কথা বলছি। আর আমার বাবা বলেছেন, তিনি বলেছেন। খোদাকে এখান থেকে যেতে শিখিয়েছে, সে এটা বলেনি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ فِي خُطْبَةِ الْحَاجَةِ ‏ ‏إِنَّ الْحَمْدَ لِلَّهِ نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ قَرَأَ ثَلَاثَ آيَاتٍ مِنْ كِتَابِ اللَّهِ ‏ { ‏اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} { ‏اتَّقُوا اللَّهَ الَّذِي ‏ ‏تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ‏} { ‏اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏وَأَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةَ الْحَاجَةِ ‏ ‏فَذَكَرَ نَحْوَ هَذَا الْحَدِيثِ إِلَّا أَنَّهُ لَمْ يَقُلْ إِنَّ ‏","","",""],[3907,3907,"","আমরা সবাই আমার বাবার হৃদয় ভেঙ্গে ঈশ্বরের প্রতি ভালবাসা নিয়ে আমাকে সাহায্য করার কথা বলেছি, ঈশ্বর যুদ্ধ শিখাকে রোধ করতে চান এবং যুদ্ধকে আরো বৃদ্ধি করতে চান। তার সমস্ত সহজাত প্রবৃত্তি দিয়ে... ...আর তারপর সে বলল আমরা কে আর কে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ أَبِي صَخْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏لَمَّا أَتَى ‏ ‏عَبْدُ اللَّهِ ‏ ‏الْجَمْرَةَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏اسْتَبْطَنَ ‏ ‏الْوَادِيَ ‏ ‏وَاسْتَقْبَلَ ‏ ‏الْكَعْبَةَ ‏ ‏وَجَعَلَ ‏ ‏الْجَمْرَةَ ‏ ‏عَلَى حَاجِبِهِ الْأَيْمَنِ ثُمَّ رَمَى بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ ثُمَّ قَالَ مِنْ هَاهُنَا وَالَّذِي لَا إِلَهَ غَيْرُهُ رَمَى الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3908,3908,"","আমরা অনেক বছর ধরে ঈশ্বর সম্পর্কে জেনেছি... ...ঈশ্বর আমাকে বলতে বলেছেন... ...তার জন্য প্রার্থনা করুন... ...আর আমি তোমার জন্য কিছু করব... আমি যা পড়েছি তার বিপরীতে খারাপ কিছু বললে আমরা আপনার কাছে এসেছি খুব ভাল করে বলেছেন আমি তাকে দেখেছি আর তাকে মনে রাখার জন্য ভাড়া করেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ عَلَيَّ الْقُرْآنَ قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَقْرَأُ عَلَيْكَ وَإِنَّمَا أُنْزِلَ عَلَيْكَ قَالَ إِنِّي ‏ ‏أَشْتَهِي أَنْ أَسْمَعَهُ مِنْ غَيْرِي قَالَ فَافْتَتَحْتُ سُورَةَ ‏ ‏النِّسَاءِ ‏ ‏فَقَرَأْتُ عَلَيْهِ فَلَمَّا بَلَغْتُ ‏ { ‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا ‏} ‏قَالَ نَظَرْتُ إِلَيْهِ وَعَيْنَاهُ ‏ ‏تَذْرِفَانِ ‏","","",""],[3909,3909,"","আমরা হিংসার দ্বারা আটকা পড়া সাহায্যের জন্য কথা বলেছি, আমার মা বলেছে আমি আমার স্বামীকে ভালবাসি, ঈশ্বর আমার স্বপ্নকে রক্ষা করেছেন। আমার ভাই আর ভাই, ঈশ্বরের প্রতি ভক্তির কারণে তার শান্তি এসেছে আর ঈশ্বরের কাছে প্রার্থনা করবে যেন সে পাপমোচনের জন্য ঈশ্বরের কাছে প্রার্থনা করে। আর একটা ভয়ানক ঝামেলা আর কোন কিছুর ক্ষতি না করে। আগুন বা কবরে, এটা ভাল ও ভাল ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏اللَّهُمَّ أَمْتِعْنِي بِزَوْجِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِأَبِي ‏ ‏أَبِي سُفْيَانَ ‏ ‏وَبِأَخِي ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْتِ اللَّهَ عَزَّ وَجَلَّ لِآجَالٍ ‏ ‏مَضْرُوبَةٍ ‏ ‏وَأَيَّامٍ مَعْدُودَةٍ وَأَرْزَاقٍ مَقْسُومَةٍ لَنْ يُعَجِّلَ شَيْئًا قَبْلَ ‏ ‏حِلِّهِ ‏ ‏أَوْ يُؤَخِّرَ شَيْئًا عَنْ ‏ ‏حِلِّهِ ‏ ‏وَلَوْ كُنْتِ سَأَلْتِ اللَّهَ عَزَّ وَجَلَّ أَنْ يُعِيذَكِ مِنْ عَذَابٍ فِي النَّارِ أَوْ عَذَابٍ فِي الْقَبْرِ كَانَ خَيْرًا وَأَفْضَلَ ‏","","",""],[3910,3910,"","সে বলেছিল বানরটা বলেছে, তার ভালবাসা তৈরি করতে হবে আর গোয়াতে যেতে হবে না। আমরা কথা বলেছি তার বুকে ওজন দিতে তার নাম তোমাকে মেরে ফেলছে।","‏ ‏قَالَ ‏ ‏وَذُكِرَ عِنْدَهُ أَنَّ الْقِرَدَةَ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أُرَاهُ قَالَ وَالْخَنَازِيرَ ‏ ‏مِمَّا ‏ ‏مُسِخَ ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَجْعَلْ لِمَسِيخٍ نَسْلًا وَلَا ‏ ‏عَقِبًا ‏ ‏وَقَدْ كَانَتْ الْقِرَدَةُ ‏ ‏أُرَاهُ قَالَ وَالْخَنَازِيرُ ‏ ‏قَبْلَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏نَحْوَهُ بِإِسْنَادِهِ وَلَمْ يَشُكَّ فِي الْخَنَازِيرِ ‏","","",""],[3911,3911,"","আমরা কথা বলেছি কিভাবে আমি ঈশ্বরকে বলতে চেষ্টা করেছি তার জন্য প্রার্থনা করা এবং আমি আমার কল্পনা থেকে দূরে থাকবো না। বড় বড় কথা আপনি ঈশ্বরের সমবেদনায় আছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّةٍ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3912,3912,"","আমরা আমার সাহায্যের কথা বলেছি, যেখানে ইশ্বর নিজের আছে আর তোমাকে দশ বছরের একটা উপহার দিবে... ...যে বিশ্বাস করে আমি তোমাকে মেরে ফেলব. আগুন বলে দাও তুমি অনেক ভালো কাজ করছো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏تَصَدَّقْنَ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ فَقَالَتْ امْرَأَةٌ وَمَا لَنَا أَكْثَرُ أَهْلِ النَّارِ قَالَ لِأَنَّكُنَّ تُكْثِرْنَ اللَّعْنَ وَتَكْفُرْنَ الْعَشِيرَ ‏","","",""],[3913,3913,"","ঈশ্বরের প্রতি ভালবাসা দেখানোর অনেক বছর আগে আমরা কথা বলেছি। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং একটি আত্মা থেকে আত্মসমর্পণ করেছেন, যে একটি অবিচারের শিকার হবে যদি একটি ছেলে এটা করেছিল, আমি প্রথম। আমি এটা করেছি প্রথম। আমি জানি, আমি কি, আমি এটা করেছি? খুন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَفْسٍ تُقْتَلُ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏الْأَوَّلِ ‏ ‏كِفْلٌ ‏ ‏مِنْ دَمِهَا ذَلِكَ بِأَنَّهُ أَوَّلُ مَنْ ‏ ‏سَنَّ ‏ ‏الْقَتْلَ ‏","","",""],[3914,3914,"","আমরা এই ব্যাপারে কিছু ভালো কাজ করেছি, কিন্তু এটা জেগে ওঠার ব্যাপার আর আমরা এমনকি কথা বলেছি কত এটা? আমার বাবা তার সাথে ঈশ্বরের সেরা কাজ করার জন্য দৃঢ়প্রতিজ্ঞ। বাবার অনুসন্ধান, ভগবান তার জন্য প্রার্থনা করেছেন আর তার এই আফসোসের কথা বলতে গিয়ে তাকে আত্মসমর্পণ করা হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏الْمَعْنَى وَهَذَا لَفْظُ ‏ ‏وَكِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏أَنْ أَبَاهُ ‏ ‏مَعْقِلَ بْنَ مُقَرِّنٍ الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏لِابْنِ مَسْعُودٍ ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّدَمُ تَوْبَةٌ قَالَ نَعَمْ ‏","","",""],[3915,3915,"","আমরা একে অপরের সাহায্য নিয়ে কথা বলেছি, আমার বাবা যে কিনা ঈশ্বরের মৃত্যুর উপর হস্তক্ষেপ করেছে, সে তার কাছে প্রার্থনা করেছে এবং সে আত্মসমর্পণ করবে এবং সে হল সেই বন্ধু যে আমাকে বলেছে জুরিরা যে কথা বলতে পারবে না তা নিয়ে কথা বলতে পারবেন না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏قَالَ ‏ ‏بَيْعُ ‏ ‏الْمُحَفَّلَاتِ ‏ ‏خِلَابَةٌ ‏ ‏وَلَا تَحِلُّ ‏ ‏الْخِلَابَةُ ‏ ‏لِمُسْلِمٍ ‏","","",""],[3916,3916,"","আমরা আমার বাবা আর তার ঈশ্বরের জন্য দুটি জীবনের সেরা দু'টি জীবনের কথা বলেছি, কিন্তু আল্লাহ তার পতাকার জন্য প্রার্থনা করেছেন এবং শান্তি আর মৃত্যুর জন্য তাকে আত্মসমর্পণ করেছেন। তার গর্ব.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏يُحَدِّثُهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏","","",""],[3917,3917,"","আমরা একটি ছেলে জয়ের কথা বলেছি এবং ঈশ্বরের দোহাই দিয়ে যান এবং আমরা একটি জায়নিিস্ট কথা বলেছি যে একটি শিখার জন্ম দিয়েছে. আমি আনন্দিত আপনি একটি ভাল প্রভাব এবং একটি ভাল প্রভাব আছে আছে আছে আছে আছে আছে আছে আছে আছে আছে আছে আছে আছে আছে. এটা তুলে নাও, তুমি আমাদের কথা শিক্ষা দিলে... ...তুমি তোমার পাপের উপর বিশ্বাস রাখো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏وَفِتَنًا وَأُمُورًا تُنْكِرُونَهَا قُلْنَا يَا رَسُولَ اللَّهِ فَمَاذَا تَأْمُرُ لِمَنْ ‏ ‏أَدْرَكَ ‏ ‏ذَلِكَ مِنَّا قَالَ تُؤَدُّونَ الْحَقَّ الَّذِي عَلَيْكُمْ وَتَسْأَلُونَ اللَّهَ الَّذِي لَكُمْ ‏","","",""],[3918,3918,"","আমরা আমার নিজের সেরাটা নিয়ে কথা বলেছি... ...আমার নিজের ব্যাপারে... ...আর একবার ক্লান্ত হয়ে পড়তে ক্লান্ত হয়ে পড়তে... ...সে বলেছিল যে তারা তাকে ছেড়ে দেবে নাকি তার নখে বেঁধে দেবে, তারপর সে এটা হারবে. হাল ছেড়ে না দিলে আমরা জানি এটা ভবিষ্যৎবানীর ব্যাপার... ...যা তার কাছে পৌঁছেছে বা তার সাথে সবসময় আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ { ‏وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا ‏} ‏قَالَ يَدْخُلُونَهَا ‏ ‏أَوْ يَلِجُونَهَا ‏ ‏ثُمَّ يَصْدُرُونَ مِنْهَا بِأَعْمَالِهِمْ قُلْتُ لَهُ ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ هُوَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ كَلَامًا هَذَا مَعْنَاهُ ‏","","",""],[3919,3919,"","আমরা আমাদের সবচেয়ে ভালো কথা বলেছি, ঈশ্বর, গন্ধ আর গন্ধটা হচ্ছে নখের হাড়ের মত, সে বলে আমি যদি বলি আর আমাকে না বলি, সে আমাকে খুন করবে। আল্লাহ্‌র বই থেকে দেয়া হয়েছে আর তিনি যা বলেছেন তা আমি পড়েছি কিন্তু তিনি তা পেয়েছেন। অথবা আপনি পড়েছেন \"আমাকে তাকে নিতে হবে না, না সে লর্ডের কাছে এসেছে।\" তিনি বলেছিলেন, \"আমি ভেবেছিলাম, আমি তাকে খুঁজে পেয়েছি।\" মনে হয় আমি আমার দিকে কিছু করতে চাই যখন সে তার প্রয়োজন দেখে। তুমি আমাদের এটা থেকে এটা শুনতে দাওনি যে আত্মার আত্মার আত্মার বৈশিষ্ট্যের কারণে... আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে তার জন ্ য , আর তার অন ্ তর আছে ন ্ যায়সঙ ্ গত । আত্মার আত্মার আত্মা, যা এক দৃষ্টিকোণ থেকে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاشِمَاتِ ‏ ‏وَالْمُتَوَشِّمَاتِ ‏ ‏وَالْمُتَنَمِّصَاتِ ‏ ‏وَالْمُتَفَلِّجَاتِ ‏ ‏لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ قَالَ فَبَلَغَ امْرَأَةً فِي الْبَيْتِ يُقَالُ لَهَا ‏ ‏أُمُّ يَعْقُوبَ ‏ ‏فَجَاءَتْ إِلَيْهِ فَقَالَتْ بَلَغَنِي أَنَّكَ قُلْتَ كَيْتَ وَكَيْتَ فَقَالَ مَا لِي لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ فَقَالَتْ إِنِّي لَأَقْرَأُ مَا بَيْنَ لَوْحَيْهِ فَمَا وَجَدْتُهُ فَقَالَ إِنْ كُنْتِ ‏ ‏قَرَأْتِيهِ فَقَدْ ‏ ‏وَجَدْتِيهِ أَمَا قَرَأْتِ ‏ { ‏مَا آتَاكُمْ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا ‏} ‏قَالَتْ بَلَى قَالَ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ قَالَتْ إِنِّي لَأَظُنُّ أَهْلَكَ يَفْعَلُونَ قَالَ اذْهَبِي فَانْظُرِي فَنَظَرَتْ فَلَمْ تَرَ مِنْ حَاجَتِهَا شَيْئًا فَجَاءَتْ فَقَالَتْ مَا رَأَيْتُ شَيْئًا قَالَ لَوْ كَانَتْ كَذَلِكَ لَمْ تُجَامِعْنَا ‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ مِنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏يُحَدِّثُهُ عَنْ ‏ ‏أُمِّ يَعْقُوبَ ‏ ‏سَمِعَهُ مِنْهَا فَاخْتَرْتُ حَدِيثَ ‏ ‏مَنْصُورٍ ‏","","",""],[3920,3920,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর তিনি বললেন ভালো মানুষ আমাকে পড়ায় আর যারা তাদেরকে দোষারোপ করে তারা আরো তিন বার। এটা একটা ব্যাপার। এটা হলো, এটা একটা কথা। এটা হলো, ঈশ্বর তাকে জিজ্ঞেস করেছেন, আমি বলেছি, আমি এটা করতে চাই না। আমি জানি না, আমি কি করব? আমি জানি, আমি এটা আমার মত। আমি জানি না, আমি এটা আমার মনে করি, আমি এটা একটা প্রশ্ন করি। আমি জানি না যে, আমি এটা আমার মত মানুষ। আমি জানি না। আমি এটা আমার মনে করি, আমি এটা একটা প্রশ্ন করি। আমি জানি না যে, আমি জানি না। আমি কি করি, আমি এটা আমার মত। আমি জানি না। আমি এটা আমার মত। আমি কি করবো? আমি এটা আমার মনে করি, আমি এটা আমার মত। আমি জানি না। আমি জানি না যে, আমি এটা আমার মত। আমি এটা আমার মনে করি, আমি এটা আমার মনে করি, আমি এটা আমার মত। তাদের মধ্যে একজনকে মারধর ও মারধর করা হতো বলে ধারণা করা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثَلَاثًا ‏ ‏أَوْ أَرْبَعًا ‏ ‏ثُمَّ يَجِيءُ قَوْمٌ تَسْبِقُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ وَيَمِينُهُ شَهَادَتَهُ قَالَ وَكَانَ أَصْحَابُنَا يَضْرِبُونَا وَنَحْنُ صِبْيَانٌ عَلَى الشَّهَادَةِ وَالْعَهْدِ ‏","","",""],[3921,3921,"","ঈশ্বর বলেছেন, ঈশ্বর যা করেছেন তা ঈশ্বরের আশীর্বাদে। আমি বলেছিলাম যে, কেন তিনি আপনার প্রতিবেশীদের কাছে আমার অতিথি হয়ে এসেছেন, যিনি একজন দাস, তিনি একজন উত্তম ব্যক্তি হওয়ার জন্য বলেছিলেন । আমি বাবাকে বললাম যে ঈশ্বরের কাছে প্রার্থনা করার পর আল্লাহ এর মঙ্গল কামনা করবেন। আমরা আমার বাবার আবেগ নিয়ে কথা বলেছি, আমরা ঈশ্বরের দোহাই দিয়ে সমস্যা সৃষ্টি করেছি এবং তিনি তা দিয়েছেন। তিনি আমাদেরকে সেই সুযোগ সম্বন্ধে মনে করিয়ে দিয়েছিলেন, যা আমাদেরকে রক্ষা করার এবং রক্ষা করার জন্য আমাদের প্রচেষ্টা করতে হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشُ ‏ ‏وَوَاصِلٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الذَّنْبِ أَعْظَمُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ قَالَ أَنْ تَجْعَلَ لِلَّهِ عَزَّ وَجَلَّ نِدًّا وَهُوَ خَلَقَكَ قَالَ قُلْتُ ثُمَّ مَاذَا قَالَ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ أَنْ يَأْكُلَ مِنْ طَعَامِكَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مَرَّةً أَنْ يَطْعَمَ مَعَكَ ‏ ‏قَالَ ثُمَّ قُلْتُ ثُمَّ مَاذَا قَالَ أَنْ تُزَانِيَ ‏ ‏بِحَلِيلَةِ ‏ ‏جَارِكَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ الْأَحْدَبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يَقُولُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الذَّنْبِ أَعْظَمُ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الذَّنْبِ أَعْظَمُ فَذَكَرَهُ ثُمَّ قَرَأَ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ ‏ ‏إِلَى ‏ ‏مُهَانًا ‏}","","",""],[3922,3922,"","আমি আমার বাবাকে যে - সর্বোত্তমটা দিতে চেয়েছিলাম, তা নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى ‏ ‏وَالْعِفَّةَ ‏ ‏وَالْغِنَى ‏","","",""],[3923,3923,"","আমরা আমার বাবার কাছে সবচেয়ে ভালো কথা বলেছি, বাবাকে জয় করার জন্য রাতে আমি আমার বাবার কাছে যা কিছু করেছি, তার সব থেকে ভালোর কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا خَلِيلًا لَاتَّخَذْتُ ‏ ‏ابْنَ أَبِي قُحَافَةَ ‏ ‏خَلِيلًا ‏","","",""],[3924,3924,"","আমরা ঈশ্বরের মঙ্গলের জন্য দুটি জীবনের সেরা দু'টি জীবনের কথা বলেছি, আমি কখনোই তার জন্য প্রার্থনা করতে দেখিনি এবং তার অন্ধকার থেকে তাকে আশীর্বাদ করা হবে। সকালে এসে হাজির হল। তার জীবন, আমরা যে - সময়ে কথা বলেছি, তার বাবার সাথে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً إِلَّا لِمِيقَاتِهَا إِلَّا أَنَّهُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏وَصَلَّى الصُّبْحَ يَوْمَئِذٍ لِغَيْرِ مِيقَاتِهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏مَعْنَاهُ ‏","","",""],[3925,3925,"","আমরা ঈশ্বরের ভালবাসার জন্য দুটি জীবনের সেরা দু'টি জীবনের কথা বলেছি, সে ঈশ্বরের কাছে প্রার্থনা করার চেষ্টা করেছে, সে তার জন্য ঈশ্বরের কাছে প্রার্থনা করেছে এবং সে নিজেকে হত্যা করেছে। সে বলল, ঈশ্বর জয়ী হয়েছে এবং সে তার জীবন দিয়েছে। ঈশ্বর এটাকে পিতা বলে সম্বোধন করেছিলেন!","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَأَنْ أَحْلِفَ تِسْعًا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُتِلَ قَتْلًا أَحَبُّ إِلَيَّ مِنْ أَنْ أَحْلِفَ وَاحِدَةً أَنَّهُ لَمْ يُقْتَلْ وَذَلِكَ أَنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَهُ نَبِيًّا وَاتَّخَذَهُ شَهِيدًا ‏ ‏قَالَ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ ‏ ‏كَانُوا يَرَوْنَ وَيَقُولُونَ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏سَمُّوهُ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[3926,3926,"","আমরা রাজাকে বলেছিলাম যে আমরা দু বছর আগে খেলা করছি, সে হয়ত বলেছে কেন সে নিচে নেমে গেছে, সে তোমার প্রভুকে ক্ষমা করবে না আর তাকে ক্ষমা করবে না, যদি সে জিততে চায়। আমরা ঈশ্বর এবং প্রভু, ঈশ্বর তাকে আদেশ দিয়েছেন, এবং তিনি এর সবচেয়ে গুরুত্বপূর্ণ ব্যক্তি, আমি আপনার সাথে মিল আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا ‏} ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ ‏","","",""],[3927,3927,"","আমরা ঈশ্বরের দোহাই কথা বলেছি আর যদি চেষ্টা করো, ঈশ্বর তাকে প্রার্থনা করেন আর মানুষকে আগুন থেকে বের করে দেন... ...তাহলে তারা এর জন্য নির্ধারিত ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ { ‏وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا ‏} ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرِدُ ‏ ‏النَّاسُ النَّارَ كُلُّهُمْ ثُمَّ ‏ ‏يَصْدُرُونَ ‏ ‏عَنْهَا بِأَعْمَالِهِمْ ‏","","",""],[3928,3928,"","আমরা একটি স্মৃতিস্তম্ভের ছেলেকে রক্ষা করার চেষ্টা করেছি, যে কিনা আমাদের সাথে কথা বলেছে কিন্তু আমরা ভয় পেয়েছি যে আমার জীবন আমার জীবনের শাসন দ্বারা আবদ্ধ হবে। আর তারপর আল্লাহ্ তা প্রার্থনা করেছেন এবং তিনি আছেন। আমার কমান্ডিং অফিসারের পদ অনুসরণ করা এবং তিনি যে পথে অংশ নিয়েছিলেন, তা অনুসরণ করা আমার জন্য সহজ ছিল না । তুমি ওর জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَّ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطًّا ثُمَّ قَالَ هَذَا سَبِيلُ اللَّهِ ثُمَّ خَطَّ خُطُوطًا عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ثُمَّ قَالَ هَذِهِ سُبُلٌ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏مُتَفَرِّقَةٌ ‏ ‏عَلَى كُلِّ سَبِيلٍ مِنْهَا شَيْطَانٌ يَدْعُو إِلَيْهِ ثُمَّ قَرَأَ ‏ { ‏إِنَّ هَذَا صِرَاطِي ‏ ‏مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ‏}","","",""],[3929,3929,"","ঈশ্বর সেই লোকেদের বলেছিলেন, যারা তাঁকে ঘন্টা শিক্ষা দেয় এবং তারা হল জীবনের উৎস । শিরোনাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏مِنْ شِرَارِ النَّاسِ مَنْ تُدْرِكُهُ السَّاعَةُ وَهُمْ أَحْيَاءٌ وَمَنْ يَتَّخِذُ الْقُبُورَ مَسَاجِدَ ‏","","",""],[3930,3930,"","ঈশ্বর তাকে বলেছিলেন, যেন লোকেরা না দেখে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَقُومُ السَّاعَةُ ‏ ‏أَوْ لَا تَقُومُ السَّاعَةُ ‏ ‏إِلَّا عَلَى شِرَارِ النَّاسِ ‏","","",""],[3931,3931,"","আমরা যে - সমস্ত উত্তম বিষয় নিয়ে কথা বলতাম, তা নিয়ে কথা বলতাম । তিনি আমাকে চান আমি যেন সে যা নিয়ে আসি এবং তিনি ঈশ্বরের কাছে যা বলেছেন তা নিয়ে কথা বলেন এবং প্রার্থনা না করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَتَكَلَّمُ فِي الصَّلَاةِ وَيُسَلِّمُ بَعْضُنَا عَلَى بَعْضٍ ‏ ‏وَيُوصِي أَحَدُنَا بِالْحَاجَةِ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمْتُ عَلَيْهِ وَهُوَ ‏ ‏يُصَلِّي فَلَمْ يَرُدَّ عَلَيَّ فَأَخَذَنِي مَا قَدُمَ وَمَا ‏ ‏حَدُثَ فَلَمَّا صَلَّى قَالَ إِنَّ ‏ ‏اللَّهَ عَزَّ وَجَلَّ يُحْدِثُ مِنْ أَمْرِهِ مَا شَاءَ وَإِنَّهُ قَدْ أَحْدَثَ أَنْ لَا تَكَلَّمُوا فِي الصَّلَاةِ ‏","","",""],[3932,3932,"","আমি আমার বাবার কথা বলেছিলাম ঘোড়ার কথা, আল্লাহ একজন মানুষকে আশীর্বাদ করুন, কিন্তু তার কোন আনন্দ নেই, কিন্তু শুনে খুশিও না। এমনকি এটা একটা অর্জনও প্রকাশ করবে না যে সে কোন গানও ব্যাখ্যা করবে না। আমরা হাত দিয়ে মাথা নত করি, বলে রাখি যে মদ মানে মৃত্যুর শক্তি আছে। তারা যে শান্তি ফিরে আসবে না তা হবে মৃত্যুর গৌরবে ফিরে আসা, এই সবই পৃথিবীর ক্ষমতার এক টুকরা। এমনকি ঈশ্বরের শক্তির ক্ষমতাও স্পর্শ করে। আমি প্রভু তাদের জন্য ভাল চেষ্টা করতে পারি তাদের হত্যা করা. তারা মনে মনে মনে মনে মনে মনে মনে মনে মনে যে সিঁড়ির কথা বলতে হতো, তারা কখনও তাদের মুখে পড়ে যেত না এবং নিজেদের মুখে পড়ে যেত না । তার জন্য প্রার্থনা করুন এবং তিনি আমার নাম মুছে দেবেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أُسَيْرِ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏هَاجَتْ رِيحٌ حَمْرَاءُ ‏ ‏بِالْكُوفَةِ ‏ ‏فَجَاءَ رَجُلٌ لَيْسَ لَهُ ‏ ‏هِجِّيرٌ ‏ ‏إِلَّا يَا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏جَاءَتْ السَّاعَةُ قَالَ وَكَانَ مُتَّكِئًا فَجَلَسَ فَقَالَ ‏ ‏إِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى لَا يُقْسَمَ مِيرَاثٌ وَلَا يُفْرَحَ بِغَنِيمَةٍ قَالَ عَدُوًّا يَجْمَعُونَ لِأَهْلِ الْإِسْلَامِ وَيَجْمَعُ لَهُمْ أَهْلُ الْإِسْلَامِ وَنَحَّى بِيَدِهِ نَحْوَ ‏ ‏الشَّامِ ‏ ‏قُلْتُ ‏ ‏الرُّومَ ‏ ‏تَعْنِي قَالَ نَعَمْ قَالَ وَيَكُونُ عِنْدَ ‏ ‏ذَاكُمْ الْقِتَالِ رِدَّةٌ شَدِيدَةٌ قَالَ فَيَشْتَرِطُ الْمُسْلِمُونَ ‏ ‏شُرْطَةً ‏ ‏لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً فَيَقْتَتِلُونَ حَتَّى يَحْجِزَ بَيْنَهُمْ اللَّيْلُ ‏ ‏فَيَفِيءَ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غَيْرُ غَالِبٍ ‏ ‏وَتَفْنَى ‏ ‏الشُّرْطَةُ ‏ ‏ثُمَّ يَشْتَرِطُ الْمُسْلِمُونَ ‏ ‏شُرْطَةً ‏ ‏لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً فَيَقْتَتِلُونَ حَتَّى يَحْجِزَ بَيْنَهُمْ اللَّيْلُ ‏ ‏فَيَفِيءَ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غَيْرُ غَالِبٍ ‏ ‏وَتَفْنَى ‏ ‏الشُّرْطَةُ ‏ ‏ثُمَّ يَشْتَرِطُ الْمُسْلِمُونَ ‏ ‏شُرْطَةً ‏ ‏لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً فَيَقْتَتِلُونَ حَتَّى يُمْسُوا ‏ ‏فَيَفِيءَ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غَيْرُ غَالِبٍ ‏ ‏وَتَفْنَى ‏ ‏الشُّرْطَةُ ‏ ‏فَإِذَا كَانَ الْيَوْمُ الرَّابِعُ ‏ ‏نَهَدَ ‏ ‏إِلَيْهِمْ بَقِيَّةُ أَهْلِ الْإِسْلَامِ فَيَجْعَلُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الدَّبْرَةَ ‏ ‏عَلَيْهِمْ فَيَقْتُلُونَ مَقْتَلَةً إِمَّا قَالَ لَا يُرَى مِثْلُهَا ‏ ‏وَإِمَّا قَالَ لَمْ نَرَ مِثْلَهَا ‏ ‏حَتَّى إِنَّ الطَّائِرَ لَيَمُرُّ بِجَنَبَاتِهِمْ فَمَا ‏ ‏يُخَلِّفُهُمْ ‏ ‏حَتَّى يَخِرَّ مَيِّتًا قَالَ فَيَتَعَادُّ بَنُو الْأَبِ كَانُوا مِائَةً فَلَا يَجِدُونَهُ بَقِيَ مِنْهُمْ إِلَّا الرَّجُلُ الْوَاحِدُ فَبِأَيِّ غَنِيمَةٍ يُفْرَحُ أَوْ أَيُّ مِيرَاثٍ يُقَاسَمُ قَالَ بَيْنَا هُمْ كَذَلِكَ إِذْ سَمِعُوا بِنَاسٍ أَكْثَرَ مِنْ ذَلِكَ قَالَ جَاءَهُمْ ‏ ‏الصَّرِيخُ ‏ ‏أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏قَدْ خَلَفَ فِي ‏ ‏ذَرَارِيِّهِمْ ‏ ‏فَيَرْفُضُونَ مَا فِي أَيْدِيهِمْ وَيُقْبِلُونَ فَيَبْعَثُونَ عَشَرَةَ فَوَارِسَ ‏ ‏طَلِيعَةً ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْلَمُ أَسْمَاءَهُمْ وَأَسْمَاءَ آبَائِهِمْ وَأَلْوَانَ خُيُولِهِمْ هُمْ خَيْرُ فَوَارِسَ عَلَى ظَهْرِ الْأَرْضِ يَوْمَئِذٍ ‏","","",""],[3933,3933,"","আমরা আমার বাবাকে তার বাবার কাছে ফিরে যেতে বলার দুটো উপায় নিয়ে কথা বলেছি কিন্তু আমি তাকে যেতে সাহায্য করতে পারছি না। আমরা মুখে ঘুমাচ্ছি আর তারপর সে এই কথা বলবে না। ও যেভাবে বলে,","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏أَوْ قَالَ نِدَاءُ ‏ ‏بِلَالٍ ‏ ‏مِنْ سَحُورِهِ فَإِنَّهُ يُؤَذِّنُ ‏ ‏أَوْ قَالَ يُنَادِي ‏ ‏لِيَرْجِعَ قَائِمَكُمْ وَلِيُنَبِّهَ نَائِمَكُمْ ثُمَّ لَيْسَ أَنْ يَقُولَ هَكَذَا ‏ ‏أَوْ قَالَ هَكَذَا ‏ ‏حَتَّى يَقُولَ هَكَذَا ‏","","",""],[3934,3934,"","আমরা আমার বাবার সাথে কথা বলেছিলাম আর আল্লাহ্‌ কসম খেয়ে বলেছিলেন যে একজন মানুষের মৃত্যুর কথা তিনি বলতে চাচ্ছেন... ...সে যা খুশি তাই করার জন্য তাকে কি নাম দিতে হবে আর করতে হবে. ঈশ্বর তা করতে পারেন এবং তিনি যা বলেছেন তা তিনি তাঁর মুখ দিয়ে এগিয়ে যান এবং বলেন, তিনি ঈশ্বরের করুণা তাঁর উপর নির্ভর করুক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْمًا قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّ هَذِهِ الْقِسْمَةَ مَا أُرِيدَ بِهَا وَجْهُ اللَّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَا عَدُوَّ اللَّهِ أَمَا لَأُخْبِرَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا قُلْتَ ‏ ‏قَالَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْمَرَّ وَجْهُهُ وَقَالَ ‏ ‏رَحْمَةُ اللَّهِ عَلَى ‏ ‏مُوسَى ‏ ‏قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ ‏","","",""],[3935,3935,"","আমরা বাবার ছেলেকে ফিরিয়ে দিতে বলেছিলাম, আমরা যে খারাপ কথা বলেছি তা আমাদের বলতে সাহায্য করেছে। আমি একজন সাহায্যকারীর ছেলের জন্য বলেছি, আমি শুধু ঈশ্বরের কাছে সাহায্য চেয়েছিলাম। সে তার কাছে আত্মসমর্পণ করল এবং তোমার রাজার পাগলামীর জন্য। কিন্তু আমরা তাকে হারিয়ে ফেলেছিলাম। ( মথি ২৪: ১৪) এরপর ঈশ্বর সেই ব্যক্তিদের বিষয়ে উল্লেখ করেছিলেন, যারা তাঁকে হারিয়ে ফেলেছিল । বাবার ছেলে একজন বেশ্যা, আমি তাকে একই কাজ করতে বলব, সে তোমার হাতে পড়ে না তার নিজের হাত বা তার সব পতাকায় না পড়লে, তোমার ঐ পাগলামির ভয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏وَابْنُ أَبِي زَائِدَةَ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ مَسْعُودٍ ‏ ‏هَلْ صَحِبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ مِنْكُمْ أَحَدٌ فَقَالَ مَا صَحِبَهُ مِنَّا أَحَدٌ وَلَكِنَّا قَدْ فَقَدْنَاهُ ذَاتَ لَيْلَةٍ فَقُلْنَا اغْتِيلَ اسْتُطِيرَ مَا فَعَلَ قَالَ فَبِتْنَا بِشَرِّ لَيْلَةٍ بَاتَ بِهَا قَوْمٌ فَلَمَّا كَانَ فِي وَجْهِ الصُّبْحِ ‏ ‏أَوْ قَالَ فِي ‏ ‏السَّحَرِ ‏ ‏إِذَا نَحْنُ بِهِ يَجِيءُ مِنْ قِبَلِ ‏ ‏حِرَاءَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ فَذَكَرُوا الَّذِي كَانُوا فِيهِ فَقَالَ إِنَّهُ ‏ ‏أَتَانِي دَاعِي الْجِنِّ فَأَتَيْتُهُمْ فَقَرَأْتُ عَلَيْهِمْ قَالَ فَانْطَلَقَ بِنَا فَأَرَانِي آثَارَهُمْ وَآثَارَ نِيرَانِهِمْ قَالَ ‏ ‏وَقَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏سَأَلُوهُ ‏ ‏الزَّادَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏قَالَ ‏ ‏عَامِرٌ ‏ ‏فَسَأَلُوهُ لَيْلَتَئِذٍ ‏ ‏الزَّادَ ‏ ‏وَكَانُوا مِنْ جِنِّ ‏ ‏الْجَزِيرَةِ ‏ ‏فَقَالَ كُلُّ عَظْمٍ ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ يَقَعُ فِي أَيْدِيكُمْ أَوْفَرَ مَا كَانَ عَلَيْهِ لَحْمًا وَكُلُّ ‏ ‏بَعْرَةٍ ‏ ‏أَوْ ‏ ‏رَوْثَةٍ ‏ ‏عَلَفٌ لِدَوَابِّكُمْ فَلَا تَسْتَنْجُوا بِهِمَا فَإِنَّهُمَا ‏ ‏زَادُ ‏ ‏إِخْوَانِكُمْ مِنْ الْجِنِّ ‏","","",""],[3936,3936,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যে আমরা তার আনন্দ সত্ত্বে ভালোর জন্য দাঙ্গা করেছি, ঈশ্বর হয়তো ঘোড়াগুলো বিক্রি করে দিয়ে চাঁদকে ফেলে দিয়েছেন তার গোপনীয়তা, আমি গরুর বিছানার সাথে শুয়ে ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّهُ حَجَّ مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَنَّهُ ‏ ‏رَمَى الْجَمْرَةَ بِسَبْعِ حَصَيَاتٍ قَالَ وَجَعَلَ ‏ ‏الْبَيْتَ ‏ ‏عَنْ يَسَارِهِ ‏ ‏وَمِنًي ‏ ‏عَنْ يَمِينِهِ وَقَالَ هَذَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3937,3937,"","আমরা একটি দেওয়ালের উপর একটি স্মৃতিকে মূল্যবান মনে করা একটি লড়াই সম্পর্কে একটি আবেগ মুক্ত করার চেষ্টা করেছি। ঈশ্বর একজন ভালো ছেলে যে তার জন্য প্রার্থনা করে এবং শব্দ বিশ্বাস করতে চায়। আমি আরো কিছু করতে পারি, মেয়েদের বিভাগ বা তাদের মন থেকে না, ঈশ্বর এটা অর্জনের জন্য বা কেন আপনি এটা প্রয়োজন বলে, আমরা একটি খেলা গঠন সম্পর্কে কথা বলেছি ঈশ্বর হয়তো বলেছিলেন যে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন যেন আমি তোমাকে বিশ্বাস করি না । ( পড়ুন, ১ করিন্থীয় ১৫: ৩৩.)","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَرًّا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلنِّسَاءِ ‏ ‏تَصَدَّقْنَ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ فَقَالَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ أَوْ مِنْ أَعْقَلِهِنَّ يَا رَسُولَ اللَّهِ فِيمَ ‏ ‏أَوْ لِمَ أَوْ بِمَ ‏ ‏قَالَ إِنَّكُنَّ تُكْثِرْنَ ‏ ‏اللَّعْنَ ‏ ‏وَتَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ ‏ ‏مِنْ ‏ ‏تَيْمِ الرِّبَابِ ‏ ‏مِنْ أَصْحَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلنِّسَاءِ تَصَدَّقْنَ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ فَقَالَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ فِيمَ وَبِمَ وَلِمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[3938,3938,"","আমরা আমাদের আবেগে বাপ্তাইজিত হয়েছি... ...আমরা যা শুনেছি, সে যখন শুনেছি... ...সে যা বলেছে তা শুনে... ...আমরা তার টাকা দিতে পারি. তার কাছ থেকে আর পছন্দ হয় নি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ نَعَمْ وَقَدْ رَفَعَهُ ‏ ‏قَالَ ‏ ‏لَا أَحَدَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ وَلِذَلِكَ حَرَّمَ ‏ ‏الْفَوَاحِشَ ‏ ‏مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْمَدْحُ مِنْ اللَّهِ عَزَّ وَجَلَّ وَلِذَلِكَ مَدَحَ نَفْسَهُ ‏","","",""],[3939,3939,"","আমি একজন সুখী ছেলে যে বলেছিল আমি এখন ঈশ্বরের চোখে এই সময়ের সব কিছু পড়েছি। সে জানে এবং সে হবে। অতীতের কথা মনে রাখার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏رَجُلًا ‏ ‏جَاءَ إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَقَالَ إِنِّي قَرَأْتُ ‏ ‏الْمُفَصَّلَ ‏ ‏كُلَّهُ فِي رَكْعَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذًّا كَهَذِّ الشِّعْرِ لَقَدْ ‏ ‏عَرَفْتُ ‏ ‏النَّظَائِرَ ‏ ‏الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرُنُ ‏ ‏بَيْنَهُنَّ قَالَ فَذَكَرَ عِشْرِينَ سُورَةً مِنْ ‏ ‏الْمُفَصَّلِ ‏ ‏سُورَتَيْنِ سُورَتَيْنِ فِي كُلِّ رَكْعَةٍ ‏","","",""],[3940,3940,"","আমরা আবেগ নিয়ে কথা বলেছি এবং একটি ভালো ইচ্ছা খুঁজে পাওয়ার প্রয়োজনীয়তা নিয়ে, তার কথোপকথনের মাধ্যমে বাবা-মা'র ব্যাপারে তার বাবার উপাসনা শুনে ঈশ্বরের কাছে খুশি হয়েছি। প্রথমে, মনে হচ্ছে সে আমার প্লেটে আছে, আমি বলেছিলাম সে যুদ্ধ করবে। আমি আমার ঠোঁটের উপর দিয়ে এমন কিছু করবো যতক্ষণ না সে বলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا قَعَدَ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ كَأَنَّهُ عَلَى ‏ ‏الرَّضْفِ ‏ ‏قُلْتُ ‏ ‏لِسَعْدٍ ‏ ‏حَتَّى يَقُومَ قَالَ حَتَّى يَقُومَ ‏ ‏قَالَ ‏ ‏حَجَّاحٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَانَ ‏ ‏سَعْدٌ ‏ ‏يُحَرِّكُ شَفَتَيْهِ بِشَيْءٍ فَقُلْتُ حَتَّى يَقُومَ قَالَ حَتَّى يَقُومَ ‏","","",""],[3941,3941,"","আমরা আবেগ আর চাহিদার জন্য একটা আকাঙ্ক্ষা তৈরি করেছি... ...যা আমরা পেয়েছি সেটা সম্পর্কে আরও বেশি তথ্য দিতে চেষ্টা করেছি, ঈশ্বরের দোহাই, কিন্তু তিনি ঈশ্বরের কাছে প্রার্থনা করুন। আমি নিশ্চিত যে আমরা ভবিষ্যদ্বাণী করেছিলাম তার কাছে প্রার্থনা করেছি... ...এবং তিনি আত্মসমর্পণ করবেন আমরা ঈশ্বরের কাছে প্রার্থনা করেছি এবং তাকে উদ্ধার করব. আর এতো অনুপ্রাণিত, এটা ঘৃণাকারীদের ব্যাপারে, আর যারা আমাকে মিথ্যা বলেছে, সবসময় বজ্রপাতের পরে থাকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏جَمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ أَرْبَعُونَ فَكُنْتُ فِي آخِرِ مَنْ أَتَاهُ قَالَ ‏ ‏إِنَّكُمْ مَنْصُورُونَ وَمُصِيبُونَ وَمَفْتُوحٌ لَكُمْ فَمَنْ أَدْرَكَ ذَلِكَ فَلْيَتَّقِ اللَّهَ وَلْيَأْمُرْ بِالْمَعْرُوفِ وَلْيَنْهَ عَنْ الْمُنْكَرِ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَلْيَصِلْ رَحِمَهُ ‏","","",""],[3942,3942,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা একটা রীতি তৈরি করেছি যেটা আমাদের মধ্যে আছে সৃষ্টিকর্তাকে ধন্যবাদ জানাতে, ঈশ্বরকে খুশি করতে পেরে খুশি যে ঈশ্বর এটা করেছেন। আল্লাহ্‌ তার জন্য প্রার্থনা করেছেন এবং আমি বলব যে ঈশ্বরের বিপথগামীতা আমাদের মধ্যে একজন যে তার কথা শুনে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ فَرُبَّ مُبَلَّغٍ أَحْفَظُ لَهُ مِنْ سَامِعٍ ‏","","",""],[3943,3943,"","আমরা একটি দাঙ্গার সৃষ্টি করেছি, যা একটি ছেলের দ্বারা প্রতারিত হওয়া কথা শুনে শোনা গেছে। ভিড়ে প্রার্থনা ছিল তার প্রার্থনা আর মৃত্যুর সময়। সে এটা তুলে ধরতে পারত না, সে যেন আমার টাকা দিতে না পারত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ وَسَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فَضْلُ صَلَاةِ الرَّجُلِ فِي الْجَمِيعِ عَلَى صَلَاتِهِ وَحْدَهُ خَمْسٌ وَعِشْرُونَ دَرَجَةً ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏شُعْبَةُ ‏ ‏لِي وَقَدْ رَفَعَهُ لِغَيْرِي قَالَ أَنَا أَهَابُ أَنْ أَرْفَعَهُ لِأَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَلَّمَا كَانَ يَرْفَعُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3944,3944,"","আমি বাবার সঙ্গে একটা ছেলের জন্য বাস করার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنِيهِ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُوَرِّقٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُفَضِّلُ صَلَاةَ الْجَمِيعِ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ بِخَمْسٍ وَعِشْرِينَ صَلَاةً كُلُّهَا مِثْلُ صَلَاتِهِ ‏","","",""],[3945,3945,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে বাবা আমার ভালবাসার কথা বলেছেন, তিনি বলেছিলেন তিনি যেতে এবং তার দিকে ফিরে যেতে প্রস্তুত। তোমরা যাও এবং যাও। তার আর ভালোদের জন্য হাত বাড়িয়ে বলা মানে, আর ভালোদের জন্য হাত বাড়িয়ে দেয়া আর ভালোদের জন্য ভালোর চিন্তা আছে। ঈশ্বরের দুঃখ হচ্ছে যে তার কোন ঈশ্বর নেই আর আমি তাকে ভালো লাগে। আমি চাই যে সে দাড়ি। আমি জানি যে সে আমার মত। আমি জানি, আমি তাকে ভালোবাসি। আমি জানি যে সে আমার কাছে এটা একটা ছোট বোন। আমি তাকে বলছি, আমি জানি যে আমি জানি, আমি জানি, আমি তাকে বলছি, আমি জানি না যে আমি জানি, আমি জানি, আমি তাকে বলছি, আমি জানি। আমি জানি না যে সে এটা একটা ছোট। আমি জানি না। আমি জানি, আমি জানি, আমি জানি, আমি জানি না যে আমি জানি না। আমি জানি, আমি জানি, আমি জানি না যে, আমি তাকে বলছি, আমি সত্যিই অনেক কিছু করতে পারি। তাকে ঈশ্বরের কাছে ক্ষমা আর দয়া বলে ডাকো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُلِّمَ فَوَاتِحَ الْخَيْرِ وَجَوَامِعَهُ وَخَوَاتِمَهُ فَقَالَ ‏ ‏إِذَا قَعَدْتُمْ فِي كُلِّ رَكْعَتَيْنِ فَقُولُوا التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ لِيَتَخَيَّرْ أَحَدُكُمْ مِنْ الدُّعَاءِ أَعْجَبَهُ إِلَيْهِ فَلْيَدْعُ بِهِ رَبَّهُ عَزَّ وَجَلَّ ‏","","",""],[3946,3946,"","আর যদি ঈশ্বরের কাছে প্রার্থনা কর, তা হলে সুসমাচারকে বলবেন না ।","‏ ‏وَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُنَبِّئُكُمْ مَا الْعَضْهُ قَالَ هِيَ النَّمِيمَةُ الْقَالَةُ بَيْنَ النَّاسِ ‏","","",""],[3947,3947,"","আর যদি সে প্রার্থনা করে, তাহলে ঈশ্বর তাকে উদ্ধার করবেন, তিনি বলবেন যে, সে এমনকি একজন বন্ধুও শিকার করবে এবং মিথ্যা বলবে।","‏ ‏وَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ يَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا وَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا ‏","","",""],[3948,3948,"","আমরা আবেগ নিয়ে কথা বলেছি যে বাবার ভালবাসার জন্য বাবার অনুসন্ধানের ব্যাপারে আমরা যা এনেছি, ঈশ্বর বলতে বাধ্য হন যে, যদি আমাকে আমার মা কখনো না নিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا مِنْ أُمَّتِي أَحَدًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[3949,3949,"","আমরা আবেগ নিয়ে কথা বলেছি যে বাবার ভালবাসার জন্য বাবার অনুসন্ধানের ব্যাপারে আমরা যা এনেছি, তা নিয়ে আমি আমার বাবার কাছে এসেছি। ঈশ্বর এটা তুলে ধরেছেন এবং তিনি তাদের বলছেন যে আমি আপনাকে হুমকি ও হুমকির মুখে ঠেলে দিতে এবং ভয় দেখাতে চাই। থাম আর পচিয়ে গান গাইতে থাক।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى ‏ ‏وَالْعَفَافَ ‏ ‏وَالْغِنَى ‏","","",""],[3950,3950,"","আমরা কামনায় বাপ্তাইজিত হয়েছি... ...আমরা আমার বাবাকে ঈশ্বরের জন্য খুজছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْرَأُ هَذَا الْحَرْفَ ‏ { ‏هَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ }","","",""],[3951,3951,"","আমরা আবেগকে নিরাময় করার চেষ্টা করেছি এবং আমার ভাইকে লুকানোর জন্য আমাদের হৃদয় রক্ষা করেছি। কালোরা আমার বাবার কাছে বলছে যে আমি যে কথা শুনেছি, সে বলছে, সে পড়ে গেছে। ঘুমের মধ্যে তাকে খুঁজে বের করে তার মুখ আমাকে থামিয়ে দিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَسْوَدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَرَأَ ‏ ‏النَّجْمَ ‏ ‏فَسَجَدَ بِهَا وَسَجَدَ مَنْ كَانَ مَعَهُ غَيْرَ أَنَّ شَيْخًا أَخَذَ كَفًّا مِنْ حَصًى ‏ ‏أَوْ تُرَابٍ ‏ ‏فَرَفَعَهُ إِلَى جَبْهَتِهِ وَقَالَ يَكْفِينِي هَذَا ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَقَدْ رَأَيْتُهُ بَعْدُ قُتِلَ كَافِرًا ‏","","",""],[3952,3952,"","আমি আমার বাবা আমাকে ভালোবাসার চেষ্টা করা সম্পর্কে কথা বলছি, আমি প্রার্থনা করছি আপনি আমাকে এটা দিতে হবে, ভিলেনের ছেলে! কিন্তু আমরা আমার কান ধরে রাখতে পারি না বলে আমরা এটা বলতে পারি না। ঐ অপরাধীর কোন গুরুতর অপরাধ এড়িয়ে যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ وَأَنَا أُصَلِّي فَقَالَ ‏ ‏سَلْ ‏ ‏تُعْطَهْ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏فَابْتَدَرْتُ ‏ ‏أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَسَبَقَنِي إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَمَا اسْتَبَقْنَا إِلَى خَيْرٍ إِلَّا سَبَقَنِي إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ مِنْ دُعَائِي الَّذِي لَا أَكَادُ أَنْ أَدَعَ اللَّهُمَّ إِنِّي أَسْأَلُكَ نَعِيمًا لَا يَبِيدُ وَقُرَّةَ عَيْنٍ لَا تَنْفَدُ وَمُرَافَقَةَ النَّبِيِّ ‏ ‏مُحَمَّدٍ ‏ ‏فِي أَعْلَى الْجَنَّةِ جَنَّةِ الْخُلْدِ ‏","","",""],[3953,3953,"","আমরা আমাদের সময়ের প্রবলতা দেখে বাপ্তাইজিত হয়েছি, আমরা বাবার চেয়ে ভালো অনুভব করার চেষ্টা করেছি। ঈশ্বর বললেন আমরা ঈশ্বরের বার্তাবাহকের সাথে আছি, তিনি আমার মতো একটি বেজমেন্টে আত্মসমর্পণ করবেন। যোগ দাও, তাহলে তিন হতে পারে, আমরা নিজেরাই খুন করবো, যদি ঐ বদমাশটা তাকে কখনো না ফেলে। পিপাসার্তীর বিশুদ্ধ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَيَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏قُبَّةٍ ‏ ‏نَحْوًا مِنْ أَرْبَعِينَ قَالَ ‏ ‏أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ قَالَ قُلْنَا نَعَمْ قَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ فَقُلْنَا نَعَمْ فَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ وَذَاكَ أَنَّ الْجَنَّةَ لَا يَدْخُلُهَا ‏ ‏إِلَّا نَفْسٌ مُسْلِمَةٌ وَمَا أَنْتُمْ مِنْ أَهْلِ الشِّرْكِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ ‏ ‏أَوْ الشَّعْرَةِ السَّوْدَاءِ فِي جِلْدِ الثَّوْرِ الْأَحْمَرِ ‏","","",""],[3954,3954,"","আমরা এক সময় শুনেছি একটি প্রথা সম্পর্কে একটি নির্দিষ্ট আবেগ, আমরা একটি স্বপ্নের কথা শুনেছি, ঈশ্বর আমার সাহায্য করে বলেছেন, আমার মৃত্যুই আপনার সেরা ঈশ্বর সবকিছুর জন্য সবকিছু দিতে হবে। সে যে তাকে উদ্ধার করতে হবে, ঘন্টা হল জনতার কাজ, এবং এটা জানে কি করা যায়, এবং আপনি আগামীকাল কি করবেন তার কাছাকাছি আপনি কি না. আমি বলেছিলাম আপনি তাকে বললেন যে আমরা করেছি. পাঁচ বছর আগে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏أُوتِيَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَفَاتِيحَ كُلِّ شَيْءٍ غَيْرَ الْخَمْسِ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏} ‏قَالَ ‏ ‏قُلْتُ لَهُ أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ نَعَمْ أَكْثَرَ مِنْ خَمْسِينَ مَرَّةً ‏","","",""],[3955,3955,"","আমরা একটা আবেগ নিয়ে কথা বলেছি... ...যে প্রভুর কথা আমরা রাজার ভালবাসার কথা শুনেছি, আমি নিশ্চিত ছিলাম যে তিনি বলেছিলেন আমি প্রথম উল্লেখ করব ঈশ্বর তাকে আত্মসমর্পণ করতে হবে, আমি মনে করি আপনি তাকে ঘৃণা করেছেন, আর আমি কখনো বলিনি সে ফোন করেছে আর সে শুধু সে ই ঈশ্বরের কাছে আমাদের করুণা চান । একটা ধূসর আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى بْنَ الْمُجَبِّرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مَاجِدٍ يَعْنِي الْحَنَفِيَّ ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ إِنِّي لَأَذْكُرُ أَوَّلَ رَجُلٍ قَطَعَهُ أُتِيَ بِسَارِقٍ فَأَمَرَ بِقَطْعِهِ وَكَأَنَّمَا أُسِفَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالُوا يَا رَسُولَ اللَّهِ كَأَنَّكَ كَرِهْتَ قَطْعَهُ قَالَ وَمَا يَمْنَعُنِي ‏ ‏لَا تَكُونُوا عَوْنًا لِلشَّيْطَانِ عَلَى أَخِيكُمْ إِنَّهُ يَنْبَغِي لِلْإِمَامِ إِذَا انْتَهَى إِلَيْهِ ‏ ‏حَدٌّ ‏ ‏أَنْ يُقِيمَهُ إِنَّ اللَّهَ عَزَّ وَجَلَّ عَفُوٌّ يُحِبُّ الْعَفْوَ ‏ { ‏وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ ‏} ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ الْحَنَفِيِّ ‏ ‏فَذَكَرَ مَعْنَاهُ وَقَالَ وَكَأَنَّمَا أُسِفَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ذُرَّ عَلَيْهِ رَمَادٌ ‏","","",""],[3956,3956,"","আমরা আমাদের আবেগ-অনুভূতি... ...একটা স্বপ্নের স্বপ্নের মধ্যে নিয়ে এসেছি... ...যে ভালোর জন্য এটা অনেক বড়. তিনি বলেছিলেন যে, তিনি দু - দিন খুঁজে পেয়েছেন আর এরপর তিনি সেই ছেলের জন্য ঈশ্বরের কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏وَكَانَ إِمَامَ مَسْجِدِ ‏ ‏عَلْقَمَةَ ‏ ‏بَعْدَ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا ‏ ‏عَلْقَمَةُ ‏ ‏الظُّهْرَ فَلَا أَدْرِي أَصَلَّى ثَلَاثًا أَمْ خَمْسًا فَقِيلَ لَهُ فَقَالَ وَأَنْتَ يَا أَعْوَرُ فَقُلْتُ نَعَمْ قَالَ ‏ ‏فَسَجَدَ سَجْدَتَيْنِ ‏ ‏ثُمَّ ‏ ‏حَدَّثَ ‏ ‏عَلْقَمَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[3957,3957,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি ... ...আমরা একটি স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের স্বপ্নের মধ্যে স্বপ্নের একটি স্বপ্নের একটি স্বপ্নের একটি স্বপ্নের একটি অনুষ্ঠান খেলতে চেষ্টা করার একটি রীতি তৈরি করেছি বংশধর হওয়ার জন্য ঈশ্বর তাকে আদেশ দিয়েছেন আর সে পাখিকে শয়তান থেকে উদ্ধার করবে এবং সে তাকে যে খাবার দিবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عِيسَى الْأَسَدِيِّ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطِّيَرَةُ ‏ ‏مِنْ الشِّرْكِ وَمَا مِنَّا إِلَّا وَلَكِنَّ اللَّهَ يُذْهِبُهُ بِالتَّوَكُّلِ ‏","","",""],[3958,3958,"","আমরা আবেগ নিয়ে কথা বলেছি... ...যে আমরা তার ভালবাসার মায়ার বাবার কাছে এসেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি তাকে দান করেছেন যদি আমি তার চেহারা দেখি, তাহলে সালামের উপর দয়া আসে, তোমার উপর আর ঈশ্বরের দয়া আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ حَتَّى أَرَى بَيَاضَ وَجْهِهِ فَمَا نَسِيتُ بَعْدُ فِيمَا نَسِيتُ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ ‏","","",""],[3959,3959,"","আমরা একটি দর্শন এবং অভিজাত দর্শন একটি দর্শন এবং একটি দর্শন একটি দর্শন এবং একটি দর্শন তৈরি করা একটি কামনা সম্পর্কে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা এবং তিনি তখন আমাকে আদেশ এবং তারপর তিনি আমাকে আদেশ হবে ( ১ পিতর ৫: ৮) যারা তা বুঝতে পারবে, তারা তা বুঝতে পারবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَسُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ السَّلْمَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَيْرُكُمْ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَخْلُفُ قَوْمٌ تَسْبِقُ شَهَادَاتُهُمْ أَيْمَانَهُمْ وَأَيْمَانُهُمْ شَهَادَاتِهِمْ ‏","","",""],[3960,3960,"","ঈশ্বরের দোহাই বলেছে যে আমি ব্যর্থ হব না। ( মথি ৬: ৯) আমরা কেবল তার আঙুলের মাধ্যমেই প্রত্যাশা করি । তোমরা দুজন খুজে পেয়েছ ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏مَنْصُورٌ ‏ ‏وَقَرَأْتُهُ عَلَيْهِ قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً ‏ ‏لَا أَدْرِي زَادَ أَمْ نَقَصَ ‏ ‏إِبْرَاهِيمُ ‏ ‏الْقَائِلُ ‏ ‏لَا يَدْرِي ‏ ‏عَلْقَمَةُ ‏ ‏قَالَ زَادَ أَوْ نَقَصَ أَوْ ‏ ‏عَبْدُ اللَّهِ ‏ ‏ثُمَّ اسْتَقْبَلَنَا فَحَدَّثْنَاهُ بِصَنِيعِهِ فَثَنَى رِجْلَهُ وَاسْتَقْبَلَ الْقِبْلَةَ وَسَجَدَ سَجْدَتَيْنِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏لَوْ حَدَثَ فِي الصَّلَاةِ شَيْءٌ لَأَنْبَأْتُكُمُوهُ وَلَكِنْ إِنَّمَا أَنَا بَشَرٌ أَنْسَى كَمَا تَنْسَوْنَ فَإِنْ نَسِيتُ فَذَكِّرُونِي وَأَيُّكُمْ مَا شَكَّ فِي صَلَاتِهِ ‏ ‏فَلْيَتَحَرَّ ‏ ‏أَقْرَبَ ذَلِكَ لِلصَّوَابِ فَلْيُتِمَّ عَلَيْهِ وَيُسَلِّمْ ثُمَّ يَسْجُدْ سَجْدَتَيْنِ ‏","","",""],[3961,3961,"","আমরা আমার ছেলের একটা দর্শন নিয়ে কথা বলেছি, তাকে আত্মসমর্পণ করতে হবে যদি সে তিন সেকেন্ড থাকে, সে তার দুটো ভালুক বানিয়ে দিত। আমি তাকে বিয়ে করেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَ ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا أَجْلَ يُحْزِنُهُ وَلَا تُبَاشِرْ الْمَرْأَةُ الْمَرْأَةَ أَجْلَ ‏ ‏تَنْعَتُهَا ‏ ‏لِزَوْجِهَا ‏","","",""],[3962,3962,"","আমরা আবেগ নিয়ে কথা বলেছি এবং একটি চাহিদার কথা বলেছি যা আমার বাবার ঈশ্বরের দৃষ্টি সম্পর্কে কথা বলেছি। আমি একজনকে বা অন্য কারো কাছে বলেছি। আমি আপনাকে তার সাথে ঘুম থেকে রোজা রাখতে বলছি। অথবা তার ছবি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ أَنَّهُ قَالَ ‏ ‏بِئْسَمَا لِأَحَدِكُمْ ‏ ‏أَوْ بِئْسَمَا لِأَحَدِهِمْ ‏ ‏أَنْ يَقُولَ نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ وَاسْتَذْكِرُوا ‏ ‏الْقُرْآنَ فَإِنَّهُ أَسْرَعُ ‏ ‏تَفَصِّيًا ‏ ‏مِنْ صُدُورِ الرِّجَالِ مِنْ النَّعَمِ بِعُقُلِهِ ‏ ‏أَوْ مِنْ ‏ ‏عُقُلِهِ ‏","","",""],[3963,3963,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে পিতা ও তার ভাগ্যের দৃষ্টি বহন করতে এনেছে। আমরা বলি, স্যাম হল কয়েক বছর পুরনো, কিন্তু ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার জন্য। প্রার্থনা করি, সেল্ম আমাদের উপর, আমার প্রভুর দয়া আছে, সে অমর, আর সে এখন মুক্ত পৃথিবী হিসেবে ভুলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَقُولُ السَّلَامُ عَلَى فُلَانٍ وَفُلَانٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فَإِنَّكُمْ إِذَا قُلْتُمْ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ سَلَّمْتُمْ عَلَى كُلِّ عَبْدٍ صَالِحٍ فِي الْأَرْضِ وَفِي السَّمَاءِ ‏","","",""],[3964,3964,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমার বাবা আর ভালোবাসার প্রতিশ্রুতি নিয়ে এসেছে। ঈশ্বর তাকে আদেশ দিয়েছেন আর বলেছেন যে তিনি তার নিরাপত্তার জন্য দায়ী। মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَزُبَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سِبَابُ الْمُؤْمِنِ فِسْقٌ وَقِتَالُهُ كُفْرٌ ‏ ‏قَالَ ‏ ‏فِي حَدِيثِ ‏ ‏زُبَيْدٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏","","",""],[3965,3965,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, আমার সময়ের শিখার আগুনে ভেসে এসেছি, প্রভুর বিষের রায় শুনে ঈশ্বর খুশি হয়েছেন। আর ঈশ্বর তার সিংহাসনকে টেনেছে, সে বাটন টেনে ধরে চলে গেছে, অথবা বলে চলে যাচ্ছে যে, এই গবিদের মহিমা এবং আঘাত করার জন্য। ছেলেটি থেকে বঞ্চিত হওয়ার হাত থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏رُكَيْنٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ حَسَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَكْرَهُ عَشْرًا ‏ ‏الصُّفْرَةَ ‏ ‏وَتَغْيِيرَ الشَّيْبِ وَجَرَّ ‏ ‏الْإِزَارِ ‏ ‏وَخَاتَمَ الذَّهَبِ ‏ ‏أَوْ قَالَ حَلْقَةَ الذَّهَبِ ‏ ‏وَالضَّرْبَ بِالْكِعَابِ وَالتَّبَرُّجَ بِالزِّينَةِ فِي غَيْرِ مَحِلِّهَا وَالرُّقَى إِلَّا بِالْمُعَوِّذَاتِ ‏ ‏وَالتَّمَائِمَ ‏ ‏وَعَزْلَ ‏ ‏الْمَاءِ ‏ ‏وَإِفْسَادَ الصَّبِيِّ مِنْ غَيْرِ أَنْ يُحَرِّمَهُ ‏","","",""],[3966,3966,"","আমরা একটা আবেগ দিয়ে আমাদের খেলতে চেষ্টা করেছি, যে ফাদার আর অন্য আরেকজনের কথা শুনতে পেয়েছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি বলেন যে তিনি আত্মসমর্পণ করবেন আমরা তোমাদের ব্যর্থ করে দিব, আর তোমাদের লোকদের কাছে ফিরে যাবো, আমি বলবো তুমি আমাকে বলবে না আমি তোমার পিছনে কি নিয়ে কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَلَيُرْفَعَنَّ لِي رِجَالٌ مِنْكُمْ ثُمَّ لَيُخْتَلَجُنَّ دُونِي فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيُقَالُ لِي إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ ‏","","",""],[3967,3967,"","আমি আমার বাবার বিরুদ্ধে তর্ক করেছি, যে ঈশ্বরের অনুগ্রহে আছে, আল্লাহ তা উদ্ধার করে নিয়ে যান আর আমি যে ছায়াতে থাকব সে ছায়াতে শান্ত থাকে। বাবা হয়তো বলেছিলেন যে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং বলেন যে, ঈশ্বর হয়তো বলেছিলেন যে, তিনি বলেছেন যে, তিনি বলতে চান যে, তার বলার আছে যে, তার আছে । তিনি বলেছেন যে তাকে বলতে হবে যে তাকে বলতে হবে যে তাকে বলতে হবে যে তাকে বলতে হবে যে তাকে বলতে হবে যে তাকে বলতে হবে যে তাকে বলতে হবে যে সে দুই শহর। হল আর আমি তাই করছি যাতে সে বলে যে আমি আমার বাবাকে হারিয়ে ফেলেছি.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏طَيِّئٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏التَّبَقُّرِ ‏ ‏فِي الْأَهْلِ وَالْمَالِ ‏ ‏فَقَالَ ‏ ‏أَبُو حَمْزَةَ ‏ ‏وَكَانَ جَالِسًا عِنْدَهُ نَعَمْ ‏ ‏حَدَّثَنِي ‏ ‏أَخْرَمُ الطَّائِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَكَيْفَ بِأَهْلٍ ‏ ‏بِرَاذَانَ ‏ ‏وَأَهْلٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَأَهْلِ كَذَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي التَّيَّاحِ ‏ ‏مَا التَّبَقُّرُ فَقَالَ الْكَثْرَةُ ‏","","",""],[3968,3968,"","আমরা যে আবেগ নিয়ে এসেছি, সে বেঁচে থাকার ছেলে খুঁজে পেয়েছে... ...যে কিনা ঈশ্বরের মৃত্যুর নাম শুনেছে. আমি যখন বাবাকে অনন্ত গরু নিয়ে এসেছিলাম, তখন আমার ভাই ও আমি ঈশ্বরকে ত্যাগ করেছিলাম এবং তার কাছে আমার প্রতিজ্ঞা করেছিলাম । লড়াই করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي الْهُذَيْلِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏وَلَكِنَّهُ أَخِي وَصَاحِبِي وَقَدْ اتَّخَذَ اللَّهُ عَزَّ وَجَلَّ صَاحِبَكُمْ ‏ ‏خَلِيلًا ‏","","",""],[3969,3969,"","আমরা আমার বাবা আর আত্মার জাদু নিয়ে প্রার্থনা করেছি, ঈশ্বরের কাছে এটা পৌঁছে দিতে হবে আর তিনি বলবেন যে তার আনন্দের শেষ দিন আছে। তিনি বললেন, আমি আমার কথা বলছি। আমি মনে করি, আমার বাবা এবং আত্মা, আমার বাবা-মা-এর মধ্যে, ঈশ্বর এই বিষয়টি নিয়ে কথা বলেছেন। বাবা খুন করার আইন নিয়ে বাইরে যেতে যাচ্ছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وَأَحْسَبُهُ رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ أَيَّامُ ‏ ‏الْهَرْجِ ‏ ‏أَيَّامٌ يَزُولُ فِيهَا الْعِلْمُ وَيَظْهَرُ فِيهَا الْجَهْلُ ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏الْهَرْجُ ‏ ‏بِلِسَانِ ‏ ‏الْحَبَشِ ‏ ‏الْقَتْلُ ‏","","",""],[3970,3970,"","আমরা একটি কামনা কথা বলেছি যে আমার বাবা ঈশ্বরের একজন মানুষ হতে জন্মগ্রহণ করেছেন, আমি আবার এটা করতে পেরে আনন্দিত। আমরা একটি প্রথার কথা বলেছি। আমি এটা নিয়ে কথা বলেছি, আমি আপনার বাবা-মা'র কাছে ফিরে এসেছি। আমি এটা করতে পেরে খুশি। আমি নিশ্চিত যে, আমি আবার একটি দাঙ্গা শুরু করেছি। আমি যদি আপনি একটি নতুন করে থাকেন, আপনি আপনার বাবা, আপনি কি জানেন? আমি আপনার বাবা, আপনি কি জানেন? আপনি জানেন, আপনি কি? আপনি জানেন, আপনি জানেন না? আপনি কি? আপনি জানেন, আপনি কি? আপনি জানেন না? আপনি যদি আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন না? আপনি জানেন, আপনি জানেন, আপনি জানেন না? আপনি কি? আপনি জানেন না? আপনি যদি আপনি জানেন, আপনি জানেন, আপনি আপনার বাবা আপনার বাবা আপনার বাবা আপনার বাবা আপনার সাথে আছেন। আপনি জানেন না। আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি কি, আপনি জানেন না। আপনি যদি আপনি আপনার বাবা আপনার বাবা আপনার বাবা জানেন। এবং আপনার বাবা আপনার বাবা আপনার বাবা জানেন। আমি বাবা-এর কথা শুনেছি, যখন ঈশ্বর এই ঘটনার পর তার বাবার সাথে কথা বলতে শুনেছি। তিনি বলেন, \"ঈশ্বর আমার শহরের সাথে আর আমার এই কাজ করতে হবে।\"","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَخْرَمِ ‏ ‏رَجُلٌ مِنْ ‏ ‏طَيِّئٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏التَّبَقُّرِ ‏ ‏فِي الْأَهْلِ وَالْمَالِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏و قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏كَيْفَ مَنْ لَهُ ثَلَاثَةُ أَهْلِينَ أَهْلٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَأَهْلٌ بِكَذَا وَأَهْلٌ بِكَذَا ‏","","",""],[3971,3971,"","আমরা আবেগ নিয়ে তৈরি হয়েছি, যে দাঙ্গার জন্য লড়াই করা দরকার। শাবানি কখনো বলে নি যে আমার বাবা শয়তান ছিলেন যে কথা বলেছিল সে কথা বলার সময় সে শয়তান। হয়ত এটাকে “ঈশ্বরের দোহাই আমরা প্রার্থনা করব আমি যা ভালোবাসি তার পতাকাকে আমরা ঈশ্বরের কাছে প্রার্থনা করব। প্রার্থনা করা হয় তার যুক্তির সময় যখন বলা হয় তখন তিনি বলেন যে আমি যা বলি তা পরবর্তী বিষয়। আমি যদি জিতি, আমি এটা নিয়ে আসবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَاحِبُ هَذِهِ الدَّارِ وَأَشَارَ بِيَدِهِ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَمَا سَمَّاهُ لَنَا ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ فَقَالَ الصَّلَاةُ عَلَى وَقْتِهَا ‏ ‏قَالَ ‏ ‏الْحَجَّاجُ ‏ ‏لِوَقْتِهَا ‏ ‏قَالَ ثُمَّ أَيٌّ قَالَ ثُمَّ بِرُّ الْوَالِدَيْنِ قَالَ ثُمَّ أَيٌّ قَالَ ثُمَّ الْجِهَادُ فِي سَبِيلِ اللَّهِ وَلَوْ اسْتَزَدْتُهُ لَزَادَنِي ‏","","",""],[3972,3972,"","আমরা আমার ছেলের একটা দর্শন নিয়ে কথা বলেছি, তাকে পৌঁছে দিতে হবে যে লোকটির সাথে লড়াই না করা পর্যন্ত তাকে মুক্তি দেয়া হবে এবং মানুষটি হবে। মিথ্যাও লিখে রাখা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَزَالُ الرَّجُلُ ‏ ‏يَصْدُقُ ‏ ‏وَيَتَحَرَّى الصِّدْقَ حَتَّى يُكْتَبَ صِدِّيقًا وَلَا يَزَالُ الرَّجُلُ يَكْذِبُ ‏ ‏وَيَتَحَرَّى الْكَذِبَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا ‏","","",""],[3973,3973,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমার বাবার মত... ...নিজের মতের ধারণার একটা রীতি তৈরি করেছি, তোমার মিটিং আমাকে ভয় থেকে দূরে সরিয়ে দেবে... ইমামের থ্রেড, আমাদের যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي لَأُخْبَرُ بِجَمَاعَتِكُمْ فَيَمْنَعُنِي الْخُرُوجَ إِلَيْكُمْ خَشْيَةُ أَنْ أُمِلَّكُمْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏فِي الْأَيَّامِ بِالْمَوْعِظَةِ خَشْيَةَ ‏ ‏السَّآمَةِ ‏ ‏عَلَيْنَا ‏","","",""],[3974,3974,"","আমরা একটি আবেগ কথা বলেছি যা অনুপ্রেরণা এবং মোটাতার প্রথার জন্য এনেছে। ঈশ্বরের দোহাই প্রার্থনা করেছেন তার কাছে আর তিনি বললেন যে ছোট ছোট ইহার পিছনে ছোট ছোট ছোটতা আছে আর প্রার্থনা করি, সালামকে ক্ষমা করতে হবে, আমার লর্ডের কাছে ক্ষমা আছে এবং সে এটা প্রভুর কাছে করেছে, সে অবশ্যই তাকে পাঠিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَمَنْصُورٍ ‏ ‏وَحَمَّادٍ ‏ ‏وَالْمُغِيرَةِ ‏ ‏وَأَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي التَّشَهُّدِ ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[3975,3975,"","আমি যখন তাকে বলেছিলাম যে, আমি একজন যিহোবার সাক্ষি । সে তাকে বিয়ে করতে দেবে যেন সে তাকে বলতে চায় সে তার কথা বলতে চায়। আমরা চেষ্টা করেছি বাবা কথা বলার আছে হয়তো ঈশ্বরের সাথে কথা বলার আছে, সে বলেছে যদি তুমি ৩ হও। তার সাথে কথা বলে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَنْتَجِي اثْنَانِ دُونَ وَاحِدٍ وَلَا تُبَاشِرُ الْمَرْأَةُ الْمَرْأَةَ ‏ ‏فَتَنْعَتَهَا ‏ ‏لِزَوْجِهَا حَتَّى كَأَنَّهُ يَنْظُرُ إِلَيْهَا ‏ ‏قَالَ أُرَى ‏ ‏مَنْصُورًا ‏ ‏قَالَ ‏ ‏إِلَّا أَنْ يَكُونَ بَيْنَهُمَا ثَوْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا كُنْتُمْ ثَلَاثَةً ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[3976,3976,"","আমরা আমাদের ভালোবাসার সর্বোত্তম বিষয়টা নিয়ে কথা বলতাম কিন্তু তাদের মধ্যে একজন ঈশ্বরের চেয়ে উত্তম । তাঁর জন্য বাপ্তিস্মের জন্য তাঁর কোনো মন্দ গুণ নেই","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَمْسَى قَالَ ‏ ‏أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ‏","","",""],[3977,3977,"","আমরা আমার বাবাকে জেতার জন্য রাতে যে রাত কাটাতে হয়েছে তার কথা বলেছিলাম, ঈশ্বর তাকে বললেন যে আমাকে ঘুমের মধ্যে দেখে নি, শয়তান আমাকে দেখেও আমাকে দেখে নি","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا ‏ ‏يَتَمَثَّلُ ‏ ‏بِمِثْلِي ‏","","",""],[3978,3978,"","আমরা একটি সুন্দর সময়ের জন্য দুই বছরের প্রেমের কথা বলেছি। তিনি বললেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাঁকে সিংহাসনে নিয়ে এসেছেন। কিন্তু ঈশ্বর জয় করেছেন এবং তাঁর ইচ্ছার জন্য তাঁর ইচ্ছা অর্জন করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطِّيَرَةُ ‏ ‏شِرْكٌ ‏ ‏الطِّيَرَةُ ‏ ‏شِرْكٌ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ يُذْهِبُهُ بِالتَّوَكُّلِ ‏","","",""],[3979,3979,"","আমরা বাবার জীবনের সেরা দুটো জীবনের কথা বলেছি, যে আমার বাবা আর তার বাবা একজন দেবতা বলে। আমি তাদের জিজ্ঞাসা করবো একটা ছেলের মেয়ে আর একটা ছেলের মেয়ে বোন যে ইতিমধ্যে অর্ধেক ব্লকা মেয়েকে খেলেছে, ঈশ্বর তাকে বললেন আমি হয়তো আমার মন হারিয়ে ফেলেছি। সে ঈশ্বরের কাছে প্রার্থনা করেছে যেন তার জন্য আত্মসমর্পণ করে এবং সে তার অর্ধ-পুরুষের ছেলের কাছে আত্মসমর্পণ করে। প্রভু প্রভু হবে প্রভুর প্রভু ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُزَيْلٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏وَسَلْمَانَ بْنِ رَبِيعَةَ ‏ ‏فَسَأَلَهُمَا عَنْ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ فَقَالَا لِلْبِنْتِ النِّصْفُ وَلِلْأُخْتِ النِّصْفُ وَأْتِ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَإِنَّهُ سَيُتَابِعُنَا فَأَتَى ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَأَخْبَرَهُ فَقَالَ قَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنْ الْمُهْتَدِينَ لَأَقْضِيَنَّ فِيهَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَضَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏لِلْبِنْتِ النِّصْفُ وَلِابْنَةِ ‏ ‏الِابْنِ السُّدُسُ وَمَا بَقِيَ فَلِلْأُخْتِ ‏","","",""],[3980,3980,"","আমরা আমার বাবার জন্য যা করেছি তার সব থেকে ভালো কথা বলেছি, সে বলবে সে এমন ভালো মানুষ হবে না যারা আমার বাবাকে আর মাঝে মাঝে আমার বাবার সাথে কথা বলতে অনেক সময় সময় থাকবে। তাকে কল করে, সে বলেছে না বলে আমি ভালো আছি, যে মারা যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَكُونَ خَيْرًا مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏بِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[3981,3981,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি... ...আমাদের কি থামতে হবে তা বলে খুশি হতে পারে। ঈশ্বরের জন্য আমরা তাঁর জন্য সবচেয়ে ভাল কিছু করেছি। আর তার বেশ্যা ও তার ওজনের পাত্রের মতো ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ ‏ ‏حَدَّثَنَا ‏ ‏صَاحِبٌ لَنَا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا ‏ ‏يُعْدِي شَيْءٌ شَيْئًا فَقَامَ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏النُّقْبَةُ ‏ ‏مِنْ الْجَرَبِ تَكُونُ ‏ ‏بِمِشْفَرِ ‏ ‏الْبَعِيرِ أَوْ ‏ ‏بِذَنَبِهِ ‏ ‏فِي الْإِبِلِ الْعَظِيمَةِ فَتَجْرَبُ كُلُّهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا أَجْرَبَ الْأَوَّلَ لَا عَدْوَى وَلَا ‏ ‏هَامَةَ ‏ ‏وَلَا ‏ ‏صَفَرَ ‏ ‏خَلَقَ اللَّهُ كُلَّ نَفْسٍ فَكَتَبَ حَيَاتَهَا وَمُصِيبَاتِهَا وَرِزْقَهَا ‏","","",""],[3982,3982,"","আমি আমার বাবাকে আমার ভাগ্যের প্রতি ভালবাসা দেখাতে বলেছিলাম । আমি এটাকে পুরোপুরি পুরোপুরি ভুল বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ وَقُمْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَلَمْ يَزَلْ قَائِمًا حَتَّى هَمَمْتُ بِأَمْرِ سَوْءٍ قَالَ قُلْنَا مَا هَمَمْتَ قَالَ هَمَمْتُ أَنْ أَجْلِسَ وَأَدَعَهُ ‏","","",""],[3983,3983,"","আমরা একটা আবেগ মুক্ত করার চেষ্টা করেছি, যা আমাদের কাছে শোনা বা ঈশ্বরকে খোঁজার চেষ্টা করার জন্য নিয়ে এসেছে। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি বললেন, তিনি প্রথমে কি শাসন করেছেন। রক্ত নিয়ে খেলো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَوَّلَ مَا يُحْكَمُ بَيْنَ الْعِبَادِ فِي الدِّمَاءِ ‏","","",""],[3984,3984,"","আমরা আমাদের নিজেদের মধ্যে যে আবেগতা ছড়িয়ে দিতে চেষ্টা করেছি, ঈশ্বর হয়ত সব গেরিলাদের বলতে পারতেন যারা কখনও বেঁচে থাকতে সক্ষম হয়েছে। আবেগ প্রকাশ করে বলা যায় এটা একটি বিরল চুল। এটা বলে যে এটা একটা বিরল চুল। এটা হল একটি ছোট চুলী চুলী, যা আমাদের কল্পনা, আমরা দেখতে পারি, এটা আমাদের কল্পনা। আমরা যা দেখতে পারি, আমরা যদি আমরা আমাদের কল্পনার মধ্যে দিয়ে যাই, আমরা শুধু একটা সুন্দর সুন্দর সুন্দর সুন্দর জিনিস। কিন্তু আমরা শুধু একটা ছোট দল, কিন্তু আমরা শুধু একটা ছোট দল, যা আমরা আমাদের মনে করি, তা হল, আমরা শুধু একটা ছোট দল, এবং আমরা আমাদের স্বপ্নের জন্য। কিন্তু আমরা আমাদের কাছে এর জন্য। কিন্তু আমরা এখানে নেই। আমরা যখন আমরা এখানে এসেছি, আমরা এখানে এসেছি, তখন আমরা সবাই আমাদের কাছে এটা একটা ছোট ছোট ছোট দল। কিন্তু আমরা যখন আমরা এখানে এসেছি, তখন আমরা আমাদের কাছে এটা একটা ছোট দল ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏يُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""],[3985,3985,"","আমরা একটা আবেগ দিয়ে চেষ্টা করেছি, যা আমাদের শোনা বা ঈশ্বরকে খোঁজার চেষ্টা করে নিয়ে এসেছে। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং সে সব গেরিলার মৃত্যুর পর সে বলবে তার জীবন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏يُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""],[3986,3986,"","আমরা যে আবেগ নিয়ে কথা বলেছি তা আমাদের শুনতে বা তা শুনতে হবে। আমি তার কাছে প্রার্থনা করব এবং আমি স্বপ্ন দেখে যাব এবং তিনি আমাকে বলবেন তিনি যেতে যাচ্ছেন তাকে আঘাত কর, মহারাজ বললেন, আল্লাহ আমার শক্তির জন্য ক্ষমা করবেন, তারা জানে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَحْكِي نَبِيًّا قَالَ كَانَ قَوْمُهُ يَضْرِبُونَهُ حَتَّى ‏ ‏يُصْرَعَ ‏ ‏قَالَ فَيَمْسَحُ جَبْهَتَهُ وَيَقُولُ اللَّهُمَّ اغْفِرْ لِقَوْمِي إِنَّهُمْ لَا يَعْلَمُونَ ‏","","",""],[3987,3987,"","আমরা আমাদের কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...যেন শুনে শোনা যায়, ঈশ্বর তার জন্য প্রার্থনা করেছেন, আর তিনি ঈশ্বরের কাছে শপথ নিয়েছেন যে তিনি... আমি আর ঈশ্বরের কাছে যা চাই, তাকে আমার হাত দিতে হবে। আমি মনে করি, তার নিজের মনে তার আবেগ আছে। আমি মনে করি, সে বলেছে, আমরা তাকে মুক্তি দিয়ে দেব। ঈশ্বর আর সন্দেহের মধ্যে... ...যে সে চলে গেছে... ...সে চলে গেছে এই বাস্তবতা দেখে...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْمًا فَقَالَ رَجُلٌ إِنَّ هَذِهِ لَقِسْمَةٌ مَا أُرِيدَ بِهَا وَجْهُ اللَّهِ قَالَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَاحْمَرَّ وَجْهُهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَظُنُّهُ قَالَ وَغَضِبَ ‏ ‏حَتَّى وَدِدْتُ أَنِّي لَمْ أُخْبِرْهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسَبُهُ ‏ ‏قَالَ ‏ ‏يَرْحَمُنَا اللَّهُ ‏ ‏وَمُوسَى ‏ ‏شَكَّ ‏ ‏شُعْبَةُ ‏ ‏فِي يَرْحَمُنَا اللَّهُ ‏ ‏وَمُوسَى ‏ ‏قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ ‏ ‏هَذِهِ لَيْسَ فِيهَا شَكٌّ قَدْ أُوذِيَ بِأَكْثَرَ مِنْ ذَلِكَ فَصَبَرَ ‏","","",""],[3988,3988,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যে আমরা সমুদ্রের মেঘ নিয়ে এসেছি, ঈশ্বর বলে যে এটা তোমার ঈশ্বর। ঈশ্বর আপনার বাবাকে আপনার কাছে পৌঁছে দিতে আমার কাছে প্রার্থনা করেছেন, আমি বলছি, একজন সিঁড়ির কথা চিন্তা করলে কি ক্ষতি হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ التَّيْمِيَّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُوعَكُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوعَكُ ‏ ‏وَعْكًا شَدِيدًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي ‏ ‏أُوعَكُ ‏ ‏وَعْكَ ‏ ‏رَجُلَيْنِ مِنْكُمْ قُلْتُ بِأَنَّ لَكَ أَجْرَيْنِ قَالَ نَعَمْ ‏ ‏أَوْ أَجَلْ ‏ ‏ثُمَّ قَالَ مَا مِنْ مُسْلِمٍ يُصِيبُهُ أَذًى شَوْكَةٌ فَمَا فَوْقَهَا إِلَّا حَطَّ اللَّهُ عَزَّ وَجَلَّ عَنْهُ خَطَايَاهُ كَمَا تَحُتُّ الشَّجَرَةُ وَرَقَهَا ‏","","",""],[3989,3989,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমার বাবাকে গোপনে লুকিয়ে রেখেছে। ঈশ্বরের কাছে প্রার্থনা করতে পারব যেন তিনি যা করেছেন, তা দেখে আমি নিজেকে রক্ষা করতে পারি। দুঃখিত। আমি দুঃখিত, আমি আমার বাবার কাছে ক্ষমা প্রার্থনা করছি। আমি আমার বাবার কাছে ক্ষমা প্রার্থনা করছি। আমি আমার বাবার কাছে ক্ষমা প্রার্থনা করছি, কারণ আমি আমার বাবার কাছে প্রার্থনা করছি। আমি আমার বাবার কাছে ক্ষমা প্রার্থনা করছি। আমি জানি, আমি আমার বাবার কাছে এটা নিয়ে আসবে। আমি তোমার কাছে ক্ষমা প্রার্থনা করছি। আমি জানি, আমি তোমার কাছে ক্ষমা প্রার্থনা করছি। আমি যদি আমার বাবার সাথে আমার বাবার সাথে কথা বলি, আমি আমার বাবার সাথে কথা বলি, আমি আমার বাবার মত আচরণ করি, আমি যদি আমার বাবাও করি, আমি আমার বাবা-মা'র কথা বলি, তাহলে আমি আমার বাবা-মা'র কাছে ক্ষমা প্রার্থনা করতে পারি। আমি যদি আমার বাবা-মাটকে জিজ্ঞেস করেন, আমি আমার বাবা-মা'র জন্য ক্ষমা চাইতেও না। আমি আমার কাছে ক্ষমা চাই, আমি আমার কাছে ক্ষমা চাই। মৃত্যু মানুষের দ্বারাই সৃষ্ট হয়েছে, যখন তারা এটা বের করেছে. তারা বলল তারা ফিরে যেতে, তারপর ফিরে যেতে হবে অথবা আকাশ একটি নির্মিত ধোঁয়া সঙ্গে সঙ্গে আসে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَأَى ‏ ‏قُرَيْشًا ‏ ‏قَدْ اسْتَعْصَوْا عَلَيْهِ قَالَ ‏ ‏اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ ‏ ‏يُوسُفَ ‏ ‏قَالَ فَأَخَذَتْهُمْ ‏ ‏السَّنَةُ ‏ ‏حَتَّى حَصَّتْ كُلَّ شَيْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْعِظَامَ ‏ ‏وَقَالَ ‏ ‏أَحَدُهُمَا حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ ‏ ‏وَجَعَلَ يَخْرُجُ مِنْ الرَّجُلِ كَهَيْئَةِ الدُّخَانِ فَأَتَاهُ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَقَالَ أَيْ ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَكْشِفَ عَنْهُمْ قَالَ فَدَعَا ثُمَّ قَالَ اللَّهُمَّ إِنْ يَعُودُوا فَعُدْ ‏ ‏هَذَا فِي حَدِيثِ ‏ ‏مَنْصُورٍ ‏ ‏ثُمَّ قَرَأَ هَذِهِ الْآيَةَ ‏ { ‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏}","","",""],[3990,3990,"","আমরা ইতোমধ্যে ঈশ্বরের উপর বিচার করার জন্য দুটি জীবন করেছি। আল্লাহ তার কাছে প্রার্থনা করেন, তাকে উদ্ধার করতে হবে, কে গান গাইতে পারবে, সে তার মুখে বলছে, \"ঈশ্বর\" বা তাঁর \"ভাল-মন্দ\"","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ مَا يُغْنِيهِ جَاءَتْ مَسْأَلَتُهُ يَوْمَ الْقِيَامَةِ خُدُوشًا ‏ ‏أَوْ ‏ ‏كُدُوحًا ‏ ‏فِي وَجْهِهِ قَالُوا يَا رَسُولَ اللَّهِ وَمَا غِنَاهُ قَالَ خَمْسُونَ دِرْهَمًا أَوْ حِسَابُهَا مِنْ الذَّهَبِ ‏","","",""],[3991,3991,"","ঈশ্বরের দোহাই দিয়ে আমাকে সাহায্য করার জন্য আমরা একে অপরের সাথে কথা বলেছি। ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি যা করেছি তা বলবো আর তারপর আমি তার মত হয়ে যাব। আমি তোমার জন্য একটা মোটা ছেলের মত হয়ে যাব।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا لِي وَلِلدُّنْيَا إِنَّمَا مَثَلِي وَمَثَلُ الدُّنْيَا كَمَثَلِ رَاكِبٍ قَالَ فِي ظِلِّ شَجَرَةٍ فِي يَوْمٍ صَائِفٍ ثُمَّ رَاحَ وَتَرَكَهَا ‏","","",""],[3992,3992,"","আমরা বলেছি, তার বাবার মৃত্যুর জন্য লজ্জার কথা... ...তার বাবার কাছে আমরা যা বানিয়েছি তা অর্থহীন এবং তা উদ্ধার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ ‏ ‏مَوْلَى ‏ ‏خُزَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏مَا صُمْنَا رَمَضَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرَ مِمَّا صُمْنَا ثَلَاثِينَ ‏","","",""],[3993,3993,"","আমরা একে অপরের কথা বলেছি এবং আমরা যা করেছি তার থেকে ভালো সব কিছুর জন্যই ঈশ্বরের ক্রোধ খোঁজা, তিনি তার কাছে অনুরোধ করেছেন যেন তিনি তা উদ্ধার করেন এবং তিনি বলেন যে তিনি যেন তিনি তা করবেন এবং তাকে বলেন। এটা তোমার আনুগত্যকে পরিপূর্ণ করার জন্য, সে পৃথিবীর রাজার সাথে ঘোরাফেরা করবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏إِنَّ لِلَّهِ فِي الْأَرْضِ مَلَائِكَةً ‏ ‏سَيَّاحِينَ ‏ ‏يُبَلِّغُونِي مِنْ أُمَّتِي السَّلَامَ ‏","","",""],[3994,3994,"","আমরা দুই বছর ধরে রাজধানী বেনকে বলেছি, ঈশ্বরের কাছে প্রার্থনা করতে হবে, কীভাবে প্রভু ঈশ্বরের কাছে প্রার্থনা করেছেন এবং তিনি তার হাত প্রথমে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أُصَلِّي بِكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ يَدَيْهِ فِي أَوَّلِ ‏","","",""],[3995,3995,"","আমরা আমার বাবা আর লর্ডের কথা বলেছি যে তিনি শান্তি প্রতিষ্ঠা করেছেন। যে কিনা একজন পণ্ডিতের জীবনে টাকা পেয়েছে এবং এখানে এই ইচ্ছা। তারা ভগবানের পেছনে কিনবে... ...আর তারপর আমরা বলি যে শেষ দিন আমরা একই হব.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينِ ‏ ‏صَبْرٍ ‏ ‏يَقْتَطِعُ ‏ ‏بِهَا مَالَ امْرِئٍ مُسْلِمٍ وَهُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ قَالَ وَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[3996,3996,"","আমরা প্রেসিডেন্টের প্রতি আনুগত্য গড়ে তুলেছি... ...যে আমরা আমার বাবা আর তার বাবাকে বলেছিলাম যে সে স্বপ্নের মানুষ। ঈশ্বরের কাছে প্রার্থনা করেছে আর তিনি তার ইচ্ছার জন্য প্রার্থনা করেছেন। প্রথমে রক্তপ্রাপ্ত মানুষদের দেয়া হয়, আমরা একটা উপায় খুঁজে বের করেছি বাবা আর তাকে জিজ্ঞেস করে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَحُمَيْدٌ الرُّؤَاسِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏شَقِيقُ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَا ‏ ‏يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[3997,3997,"","আমরা গত দুই বছর ধরে আমাদের কিছু চেষ্টা করেছি। আল্লাহ আমাদের প্রার্থনা করেন, তাঁর কাছে যেন তিনি থাকেন এবং আমাদের দ্বারা আমাদের উদ্ধার করা না হয়, যারা গালটি মার খেয়েছে এবং ইহুদিকে বলে অভিহিত করে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ وَشَقَّ ‏ ‏الْجُيُوبَ ‏ ‏وَدَعَا ‏ ‏بِدَعْوَى ‏ ‏الْجَاهِلِيَّةِ ‏","","",""],[3998,3998,"","ঈশ্বর এবং ঈশ্বর একটি অঙ্গ সংরক্ষণের পর, আমরা একটি ভ্রাতৃসমাজের কথা বলেছি এবং আমার পিতার দ্বারা পরিত্রাণ লাভ করেছে। এবং ঈশ্বর ভ্রুণে আছেন, তিনি ভ্রুন এবং ভাই সম্পর্কে তিনি বলেন যে তিনি বলেন, ঈশ্বরের প্রার্থনা হবে। তার কাছে এবং তার কাছে... ...আমি সিদ্ধান্ত নিয়েছি যে তুমি একজন পাবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏الْجَنَّةُ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلْجَنَّةُ ‏ ‏أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ وَالنَّارُ مِثْلُ ذَلِكَ ‏","","",""],[3999,3999,"","আমরা ঈশ্বরের দোহাই দিয়ে বলছি, সে আমার ভালো মানুষদের দেবে, যারা তাদের দোষ দিবে, আর তারা তাদের দোষ দিবে, আর তারপর তারা আসবে সে-ই যে হবে সেই ব ্ যক ্ তি , যে ব ্ যক ্ তি এই সমর ্ থ হবে , সেই ব্যক্তি হবেন সেই ব্যক্তি, যিনি সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হলেন সেই ব্যক্তি, যিনি হলেন রাজা । তাদের দেখেছি.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَجِيءُ قَوْمٌ تَسْبِقُ شَهَادَتُهُمْ أَيْمَانَهُمْ وَأَيْمَانُهُمْ شَهَادَتَهُمْ ‏","","",""],[4000,4000,"","আমরা অনেক বছর ধরে আমার বাবার টাকার অনুসন্ধানের কথা বলেছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং দুটি বাদামি চোখ সমর্পণ করেছেন এবং এখনও তার বইয়ের মধ্যে পাপ আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُمَيْرِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَرَأْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً وَإِنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏لَهُ ‏ ‏ذُؤَابَةٌ ‏ ‏فِي الْكُتَّابِ ‏","","",""]];
